public static function init() {
	add_action( 'init', array( __CLASS__, 'register_post_type' ) );
	add_action( 'template_redirect', array( __CLASS__, 'payment_copy_view' ), -100 );
	add_action( 'add_meta_boxes_tkd_invoice', static function() { add_meta_box( 'tkd-payment-copy', 'Реквізити для Viber та месенджерів', array( 'TKD_FO_Invoices', 'payment_copy_box' ), 'tkd_invoice', 'normal', 'high' ); } );
	add_action( 'add_meta_boxes_tkd_invoice', array( __CLASS__, 'meta_boxes' ) );
	add_action( 'save_post_tkd_invoice', array( __CLASS__, 'save_invoice' ), 20, 3 );
	add_filter( 'script_loader_src', array( __CLASS__, 'bank_choice_script_version' ), 10, 2 );
	add_action( 'admin_post_tkd_fo_create_invoice_from_order', array( __CLASS__, 'create_from_order' ) );
	add_action( 'admin_post_tkd_fo_archive_manager_invoice', array( __CLASS__, 'archive_manager_invoice' ) );
	add_action( 'admin_post_tkd_fo_split_order_invoices', array( __CLASS__, 'split_order_invoices' ) );
	add_action( 'admin_post_tkd_fo_print_invoice', array( __CLASS__, 'print_invoice' ) );
	add_action( 'admin_post_tkd_fo_download_invoice_pdf', array( __CLASS__, 'download_invoice_pdf' ) );
	add_action( 'admin_head', array( __CLASS__, 'mobile_invoice_links' ) );
	add_action( 'admin_post_tkd_fo_save_settings', array( __CLASS__, 'save_settings' ) );
	add_action( 'admin_menu', array( __CLASS__, 'settings_menu' ), 30 );
	add_filter( 'manage_tkd_invoice_posts_columns', array( __CLASS__, 'columns' ) );
	add_action( 'manage_tkd_invoice_posts_custom_column', array( __CLASS__, 'column_value' ), 10, 2 );
	add_filter( 'post_date_column_time', array( __CLASS__, 'append_author_to_date_column' ), 20, 4 );
	add_filter( 'post_row_actions', array( __CLASS__, 'row_actions' ), 10, 2 );
}

public static function bank_choices_for_seller( $seller ) {
	if ( 'no_vat' === $seller ) { return TKD_FO_DB::no_vat_bank_profiles(); }
	if ( 'fop_md' !== $seller ) { return array(); }
	$profiles = TKD_FO_DB::seller_profiles();
	$raif = array_intersect_key( $profiles['fop_md'], array_flip( array( 'tax_id', 'bank_name', 'iban', 'mfo' ) ) );
	$raif['label'] = 'Михеда Райффайзен';
	$raif['recipient_name'] = $profiles['fop_md']['legal_name'];
	return array(
		'raiffeisen' => $raif,
		'md_privat' => array(
			'label' => 'Михеда ПриватБанк', 'recipient_name' => 'ФОП Михеда Данііл Олегович',
			'tax_id' => '3810104379', 'bank_name' => 'АТ КБ «ПРИВАТБАНК»',
			'iban' => 'UA723052990000026003020410904', 'mfo' => '305299',
		),
	);
}

public static function selectable_bank_choices( $seller, $existing_key = null ) {
	$banks = self::bank_choices_for_seller( $seller );
	if ( 'fop_md' !== $seller ) { return $banks; }
	if ( null !== $existing_key && 'raiffeisen' === self::normalize_bank_key( $seller, $existing_key ) ) {
		$banks['raiffeisen']['label'] .= ' — чинний історичний рахунок';
		return $banks;
	}
	return array_intersect_key( $banks, array( 'md_privat' => true ) );
}

private static function normalize_bank_key( $seller, $key ) {
	if ( 'fop_eo' === $seller ) { return 'bank_emeo'; }
	// Older MD invoices contain pumb, privat, raiffeisen or no key; none meant the new account.
	if ( 'fop_md' === $seller ) { return 'md_privat' === $key ? 'md_privat' : 'raiffeisen'; }
	$banks = TKD_FO_DB::no_vat_bank_profiles();
	return isset( $banks[ $key ] ) ? $key : 'pumb';
}

public static function save_invoice( $post_id, $post, $update ) {
	if ( self::$saving || wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}
	if ( ! isset( $_POST['tkd_fo_invoice_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['tkd_fo_invoice_nonce'] ) ), 'tkd_fo_save_invoice' ) ) {
		return;
	}
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		return;
	}

	$seller      = self::normalize_seller_key( isset( $_POST['tkd_fo_seller_key'] ) ? wp_unslash( $_POST['tkd_fo_seller_key'] ) : 'no_vat' );
	$submitted_seller = isset( $_POST['tkd_fo_seller_key'] ) && is_string( $_POST['tkd_fo_seller_key'] ) ? sanitize_key( wp_unslash( $_POST['tkd_fo_seller_key'] ) ) : '';
	$existing_seller = (string) get_post_meta( $post_id, '_tkd_fo_seller_key', true );
	if ( ! in_array( $submitted_seller, array( 'no_vat', 'fop_pm', 'fop_rv', 'fop_tp', 'fop_md', 'fop_eo', 'vat' ), true ) ) { wp_die( 'Оберіть продавця рахунку.' ); }
	$linked_order = self::linked_order_id( $post_id );
	if ( $linked_order && $submitted_seller !== (string) get_post_meta( $linked_order, '_tkd_fo_checkout_seller_key', true ) ) { wp_die( 'Спочатку погодьте продавця в замовленні у блоці «Продавець, оплата й доставка». Рахунок не змінено.' ); }
	if ( $linked_order && $submitted_seller !== $existing_seller ) { wp_die( 'Змінюйте продавця пов’язаного рахунку через погодження умов у замовленні. Рахунок не змінено.' ); }
	$bank_key = isset( $_POST['tkd_fo_bank_key'] ) && is_string( $_POST['tkd_fo_bank_key'] ) ? sanitize_key( wp_unslash( $_POST['tkd_fo_bank_key'] ) ) : get_post_meta( $post_id, '_tkd_fo_bank_key', true );
	if ( 'fop_md' === $seller ) {
		$old_md_bank = 'fop_md' === $existing_seller ? get_post_meta( $post_id, '_tkd_fo_bank_key', true ) : null;
		if ( null === $old_md_bank && '' === $bank_key ) { $bank_key = 'md_privat'; }
		$allowed_banks = self::selectable_bank_choices( 'fop_md', $old_md_bank );
		if ( ! isset( $allowed_banks[self::normalize_bank_key( 'fop_md', $bank_key )] ) ) { wp_die( 'Для нового рахунку Дані доступний ПриватБанк. Райффайзен приховано; історичні рахунки збережено.' ); }
	}
	$bank_key = self::normalize_bank_key( $seller, $bank_key );
	$old_seller  = get_post_meta( $post_id, '_tkd_fo_seller_key', true );
	$old_number  = (string) get_post_meta( $post_id, '_tkd_fo_invoice_number', true );
	$number      = isset( $_POST['tkd_fo_invoice_number'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_invoice_number'] ) ) : '';
	$date        = isset( $_POST['tkd_fo_invoice_date'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_invoice_date'] ) ) : wp_date( 'Y-m-d' );
	$status      = isset( $_POST['tkd_fo_invoice_status'] ) ? sanitize_key( wp_unslash( $_POST['tkd_fo_invoice_status'] ) ) : 'draft';
	$status      = array_key_exists( $status, self::status_labels() ) ? $status : 'draft';
	if ( $linked_order ) {
		$archived = get_post_meta( $post_id, '_tkd_fo_invoice_status', true ) === 'cancelled' || get_post_status( $post_id ) === 'trash';
		if ( $archived && $status !== 'cancelled' ) {
			wp_die( 'Цей рахунок в архіві. Новий чинний рахунок формується в замовленні; історичний документ не відновлено.' );
		}
		if ( $status === 'cancelled' && ! $archived ) {
			$allowed = self::manager_archive_guard( $post_id );
			if ( is_wp_error( $allowed ) ) { wp_die( $allowed->get_error_message() ); }
		}
	}

	if ( $seller !== $old_seller && $number && $number === $old_number ) {
		$number = 'vat' === $seller ? '' : self::next_no_vat_number( $date, $seller );
	}
	if ( 'vat' !== $seller && ! $number ) {
		$number = self::next_no_vat_number( $date, $seller );
	}

	$error = '';
	if ( 'vat' === $seller && ! $number ) {
		$error  = 'Для продавця з ПДВ введіть актуальний номер рахунку від бухгалтера.';
		$status = 'draft';
	} elseif ( $number && self::number_exists( $seller, $number, $post_id ) ) {
		$error  = 'Рахунок із таким номером уже існує для цього продавця.';
		$number = '';
		$status = 'draft';
	}

	if ( $linked_order ) {
		// Never trust stale/tampered invoice-editor fields for order-managed pricing.
		// Preserve the invoice snapshot, including gift markers and historic totals.
		$items = get_post_meta( $post_id, '_tkd_fo_invoice_items', true );
		if ( ! is_array( $items ) ) { wp_die( 'Не вдалося прочитати товари рахунку. Перевірте пов’язане замовлення; рахунок не змінено.' ); }
		$totals = array();
		foreach ( array( 'items_subtotal', 'discount', 'subtotal', 'vat', 'total' ) as $key ) {
			$totals[ $key ] = (float) get_post_meta( $post_id, '_tkd_fo_invoice_' . $key, true );
		}
	} else {
		$items    = self::sanitize_items( isset( $_POST['tkd_fo_items'] ) ? wp_unslash( $_POST['tkd_fo_items'] ) : array() );
		$discount = max( 0, TKD_FO_DB::decimal( isset( $_POST['tkd_fo_invoice_discount'] ) ? wp_unslash( $_POST['tkd_fo_invoice_discount'] ) : 0, 2 ) );
		$totals = self::calculate_totals( $items, $seller, $discount );
	}
	if ( ! $items && 'draft' !== $status ) {
		$error  = $error ? $error : 'Додайте хоча б одну позицію номенклатури.';
		$status = 'draft';
	}

	update_post_meta( $post_id, '_tkd_fo_seller_key', $seller );
	update_post_meta( $post_id, '_tkd_fo_bank_key', $bank_key );
	update_post_meta( $post_id, '_tkd_fo_invoice_number', $number );
	update_post_meta( $post_id, '_tkd_fo_invoice_date', $date );
	update_post_meta( $post_id, '_tkd_fo_invoice_status', $status );
	if ( ! $linked_order ) {
		update_post_meta( $post_id, '_tkd_fo_invoice_items', $items );
		update_post_meta( $post_id, '_tkd_fo_invoice_items_subtotal', number_format( $totals['items_subtotal'], 2, '.', '' ) );
		update_post_meta( $post_id, '_tkd_fo_invoice_discount', number_format( $totals['discount'], 2, '.', '' ) );
		update_post_meta( $post_id, '_tkd_fo_invoice_subtotal', number_format( $totals['subtotal'], 2, '.', '' ) );
		update_post_meta( $post_id, '_tkd_fo_invoice_vat', number_format( $totals['vat'], 2, '.', '' ) );
		update_post_meta( $post_id, '_tkd_fo_invoice_total', number_format( $totals['total'], 2, '.', '' ) );
		update_post_meta( $post_id, '_tkd_fo_manual_pricing', '1' );
	}

	$buyer_type = isset( $_POST['tkd_fo_buyer_type'] ) && 'company' === $_POST['tkd_fo_buyer_type'] ? 'company' : 'person';
	update_post_meta( $post_id, '_tkd_fo_buyer_type', $buyer_type );
	foreach ( self::buyer_fields() as $key => $label ) {
		$value = isset( $_POST[ 'tkd_fo_' . $key ] ) ? sanitize_text_field( wp_unslash( $_POST[ 'tkd_fo_' . $key ] ) ) : '';
		update_post_meta( $post_id, '_tkd_fo_' . $key, $value );
	}

	if ( $error ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', $error );
	} else {
		delete_post_meta( $post_id, '_tkd_fo_invoice_error' );
	}
	self::sync_order( $post_id, $status, $items, $totals, (bool) $linked_order );

	self::$saving = true;
	wp_update_post(
		array(
			'ID'         => $post_id,
			'post_title' => $number ? 'Рахунок ' . $number : 'Чернетка рахунку #' . $post_id,
			'post_status'=> 'publish',
		)
	);
	self::$saving = false;
	if ( ! $error && isset( $_POST['post_ID'] ) && absint( $_POST['post_ID'] ) === (int) $post_id ) {
		TKD_FO_Orders::claim_responsibility( self::linked_order_id( $post_id ), 'Збережено рахунок № ' . $number );
	}
}

private static function sanitize_items( $raw_items ) {
	$items = array();
	if ( ! is_array( $raw_items ) ) {
		return $items;
	}
	foreach ( $raw_items as $raw ) {
		if ( ! is_array( $raw ) ) {
			continue;
		}
		$name  = sanitize_textarea_field( isset( $raw['name'] ) ? $raw['name'] : '' );
		$qty   = TKD_FO_DB::decimal( isset( $raw['quantity'] ) ? $raw['quantity'] : 0, 3 );
		$price = TKD_FO_DB::decimal( isset( $raw['unit_price'] ) ? $raw['unit_price'] : 0, 2 );
		if ( ! $name || $qty <= 0 || $price < 0 ) {
			continue;
		}
		$items[] = array(
			'sku'        => strtoupper( sanitize_text_field( isset( $raw['sku'] ) ? $raw['sku'] : '' ) ),
			'name'       => $name,
			'unit'       => sanitize_text_field( isset( $raw['unit'] ) ? $raw['unit'] : 'шт' ),
			'quantity'   => $qty,
			'unit_price' => $price,
		);
	}
	return $items;
}

public static function calculate_totals( $items, $seller, $discount = 0 ) {
	$items_subtotal = 0;
	foreach ( $items as $item ) {
		$items_subtotal += (float) $item['quantity'] * (float) $item['unit_price'];
	}
	$items_subtotal = round( $items_subtotal, 2 );
	$discount       = min( max( 0, round( (float) $discount, 2 ) ), $items_subtotal );
	$subtotal       = round( $items_subtotal - $discount, 2 );
	$rate     = max( 0, (float) get_option( 'tkd_fo_vat_rate', '20' ) );
	$vat      = 'vat' === $seller ? round( $subtotal * $rate / 100, 2 ) : 0;
	return array( 'items_subtotal' => $items_subtotal, 'discount' => $discount, 'subtotal' => $subtotal, 'vat' => $vat, 'total' => round( $subtotal + $vat, 2 ) );
}

private static function linked_order_id( $invoice_id ) {
	$order_id = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
	if ( $order_id && 'tkd_order' === get_post_type( $order_id ) ) {
		return $order_id;
	}
	$orders = get_posts(
		array(
			'post_type'      => 'tkd_order',
			'post_status'    => 'any',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'meta_key'       => '_tkd_fo_invoice_id',
			'meta_value'     => absint( $invoice_id ),
		)
	);
	if ( $orders ) {
		$order_id = absint( $orders[0] );
		update_post_meta( $invoice_id, '_tkd_fo_order_id', $order_id );
		return $order_id;
	}
	return 0;
}

private static function sync_order( $invoice_id, $status, $items, $totals, $preserve_order_pricing = false ) {
	$order_id = self::linked_order_id( $invoice_id );
	// Cancelling a document does not cancel its order or release its reservation.
	// Keep the original backlink, number, lines and payment references for history.
	if ( $order_id && ( $status === 'cancelled' || get_post_status( $invoice_id ) === 'trash' ) ) { return; }
	$invoice_seller = self::normalize_seller_key( get_post_meta( $invoice_id, '_tkd_fo_seller_key', true ) );
	if ( ! $order_id && in_array( $status, array( 'issued', 'paid' ), true ) ) {
		$order_id = wp_insert_post( array( 'post_type' => 'tkd_order', 'post_status' => 'publish', 'post_title' => 'Ручне замовлення — рахунок #' . $invoice_id ) );
		if ( is_wp_error( $order_id ) || ! $order_id ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', 'Не вдалося створити пов’язане замовлення.' );
			return;
		}
		$order_number = 'TKD-' . wp_date( 'Ymd' ) . '-' . str_pad( (string) $order_id, 5, '0', STR_PAD_LEFT );
		wp_update_post( array( 'ID' => $order_id, 'post_title' => $order_number . ' — ' . get_post_meta( $invoice_id, '_tkd_fo_buyer_name', true ) ) );
		update_post_meta( $invoice_id, '_tkd_fo_order_id', $order_id );
		update_post_meta( $order_id, '_tkd_order_number', $order_number );
		update_post_meta( $order_id, '_tkd_customer_name', get_post_meta( $invoice_id, '_tkd_fo_buyer_name', true ) );
		update_post_meta( $order_id, '_tkd_customer_phone', get_post_meta( $invoice_id, '_tkd_fo_buyer_phone', true ) );
		update_post_meta( $order_id, '_tkd_customer_email', get_post_meta( $invoice_id, '_tkd_fo_buyer_email', true ) );
		update_post_meta( $order_id, '_tkd_payment_method', 'Безготівкова оплата за рахунком (IBAN)' );
		update_post_meta( $order_id, '_tkd_created_at', current_time( 'mysql' ) );
	}

	if ( ! $order_id ) {
		return;
	}
	$current_order_seller = sanitize_key( (string) get_post_meta( $order_id, '_tkd_fo_checkout_seller_key', true ) );
	if ( '' === $current_order_seller && '' !== $invoice_seller ) {
		update_post_meta( $order_id, '_tkd_fo_checkout_seller_key', $invoice_seller );
	}
	self::register_order_invoice( $order_id, $invoice_id );
	// A seller-specific invoice is only one document package inside the order.
	// Editing it must not replace the order's complete historical lines or total.
	if ( '1' === (string) get_post_meta( $invoice_id, '_tkd_fo_split_invoice', true ) ) {
		return;
	}
	// An unpaid invoice that the customer replaced with LiqPay stays in the
	// document history, but must no longer rewrite the live order or its status.
	if ( 'liqpay' === (string) get_post_meta( $order_id, '_tkd_fo_manager_payment_override', true ) ) {
		return;
	}
	if ( ! $preserve_order_pricing ) {
		update_post_meta( $order_id, '_tkd_fo_invoice_id', $invoice_id );
		update_post_meta( $order_id, '_tkd_fo_order_items', $items );
		update_post_meta( $order_id, '_tkd_fo_order_discount', number_format( isset( $totals['discount'] ) ? $totals['discount'] : 0, 2, '.', '' ) );
		update_post_meta( $order_id, '_tkd_confirmed_amount', number_format( $totals['total'], 2, '.', '' ) );
		update_post_meta( $order_id, '_tkd_client_total', number_format( $totals['total'], 2, '.', '' ) );
		update_post_meta( $order_id, '_tkd_fo_invoice_pricing_locked', '1' );
		$bundle_name = trim( (string) get_post_meta( $order_id, '_tkd_fo_bundle_name', true ) );
		if ( $items && ! $bundle_name ) {
			update_post_meta( $order_id, '_tkd_product_name', $items[0]['name'] );
			update_post_meta( $order_id, '_tkd_product_qty', $items[0]['quantity'] );
			if ( isset( $items[1] ) ) {
				update_post_meta( $order_id, '_tkd_product_extra', $items[1]['name'] );
				update_post_meta( $order_id, '_tkd_product_extra_qty', $items[1]['quantity'] );
			} else {
				delete_post_meta( $order_id, '_tkd_product_extra' );
				delete_post_meta( $order_id, '_tkd_product_extra_qty' );
			}
		} elseif ( $bundle_name && isset( $items[2] ) ) {
			update_post_meta( $order_id, '_tkd_product_extra', $items[2]['name'] );
			update_post_meta( $order_id, '_tkd_product_extra_qty', $items[2]['quantity'] );
		} elseif ( $bundle_name ) {
			delete_post_meta( $order_id, '_tkd_product_extra' );
			delete_post_meta( $order_id, '_tkd_product_extra_qty' );
		}
	}

	$current = get_post_meta( $order_id, '_tkd_status', true );
	if ( 'issued' === $status && ! in_array( $current, array( 'paid', 'shipped' ), true ) ) {
		update_post_meta( $order_id, '_tkd_status', 'invoice_pending' );
	} elseif ( 'paid' === $status && 'shipped' !== $current ) {
		update_post_meta( $order_id, '_tkd_status', 'paid' );
	}
	$reservation = TKD_FO_Orders::reconcile_reserved_order( $order_id );
	if ( ! is_wp_error( $reservation ) ) {
		TKD_FO_Orders::sync_order_status( $order_id );
	}
}

	public static function ensure_manager_draft( $order_id, $bank_key = '' ) {
		global $wpdb;
		$order_id = absint( $order_id );
		if ( ! current_user_can( 'manage_tkd_felicity' ) || ! current_user_can( 'edit_post', $order_id ) || get_post_type( $order_id ) !== 'tkd_order' || in_array( get_post_status( $order_id ), array( 'trash', 'auto-draft' ), true ) ) { return new WP_Error( 'invoice_access', 'Недостатньо прав або замовлення недоступне.' ); }
		// Same mutex as manager terms: do not build an invoice halfway through seller reconciliation.
		$mutex = 'tkd_manager_terms_' . substr( hash( 'sha256', $wpdb->prefix . '|' . $order_id ), 0, 43 );
		if ( (string) $wpdb->get_var( $wpdb->prepare( 'SELECT GET_LOCK(%s,0)', $mutex ) ) !== '1' ) { return new WP_Error( 'invoice_busy', 'Інший менеджер уже зберігає умови або формує рахунок. Оновіть замовлення за кілька секунд.' ); }
		try {
		wp_cache_delete( $order_id, 'post_meta' );
        $wayforpay_owned = get_post_meta($order_id,'_tkd_solar_wfp_binding_v1',true) !== '';
        $svitloe_wfp_owned = get_post_meta($order_id,'_tkd_svitloe_wfp_binding_v1',true) !== '';
        $svitloe_wfp = $svitloe_wfp_owned && is_callable(array('SV_WFP_Documents','invoice_authorized')) && SV_WFP_Documents::invoice_authorized($order_id);
        if($svitloe_wfp_owned && !$svitloe_wfp)return new WP_Error('invoice_svitloe_wfp','Підтвердіть доставку вже оплаченої покупки в блоці Світло Є — WayForPay.');
        $wayforpay = $wayforpay_owned && is_callable(array('FS_WFP_Documents','invoice_authorized')) && FS_WFP_Documents::invoice_authorized($order_id);
        if($wayforpay_owned && !$wayforpay) return new WP_Error('invoice_wayforpay','Підтвердіть доставку вже оплаченого WayForPay у його окремому блоці. Продавця або суму не змінюйте.');
        $wayforpay = $wayforpay || $svitloe_wfp;
		$context = self::manager_invoice_context( $order_id );
		if ( is_wp_error( $context ) ) { return $context; }
		$existing = $context['active'];
		if ( $existing ) {
			if ( ! current_user_can( 'edit_post', $existing ) ) { return new WP_Error( 'invoice_link', 'Немає доступу до чинного рахунку.' ); }
			return $existing;
		}
		// A verified paid bank basket may be documented, never repriced or reassigned here.
		$rv_bank = ( is_callable( array( 'TKD_TI_RV_PayParts', 'invoice_authorized' ) ) && TKD_TI_RV_PayParts::invoice_authorized( $order_id ) )
			|| ( is_callable( array( 'TKD_TI_Lera_LiqPay', 'invoice_authorized' ) ) && TKD_TI_Lera_LiqPay::invoice_authorized( $order_id ) );
		$mono_bank = is_callable( array( 'TKD_TI_Mono', 'invoice_authorized' ) ) && TKD_TI_Mono::invoice_authorized( $order_id );
		$rv_bank = $rv_bank || $mono_bank;
		$paid_liqpay = is_callable( array( 'TKD_FO_Paid_LiqPay_Documents', 'invoice_authorized' ) ) && TKD_FO_Paid_LiqPay_Documents::invoice_authorized( $order_id );
		// Document the first full bank payment only after the same strict, fresh terms review.
		// This does not enable editing prices on paid orders or reuse credit-provider payments.
		$initial_bank = false;
		if ( ! $rv_bank && ! $paid_liqpay && ! $wayforpay && get_post_meta( $order_id, '_tkd_status', true ) === 'paid'
			&& is_callable( array( 'TKD_NP_COD_Adoption', 'manager_terms_snapshot' ) )
			&& is_callable( array( 'TKD_FO_Commerce', 'manager_terms_confirmed' ) ) && TKD_FO_Commerce::manager_terms_confirmed( $order_id ) ) {
			$review = TKD_NP_COD_Adoption::manager_terms_snapshot( $order_id, 'iban', get_post_meta( $order_id, '_tkd_np_delivery_method', true ),
				'Створення першого рахунку за вже зарахованою повною банківською оплатою', get_post_meta( $order_id, '_tkd_fo_checkout_seller_key', true ) );
			if ( is_wp_error( $review ) ) { return $review; }
			$initial_bank = ! empty( $review['initial_bank_terms'] ) && ! empty( $review['bank_seller_alignment'] ) && empty( $review['invoice_id'] );
		}
		$guard = ( $rv_bank || $paid_liqpay || $wayforpay || $initial_bank ) ? true : TKD_FO_Orders::editor_pricing_guard( $order_id, 0, TKD_FO_Payments::order_total( $order_id ) );
		if ( is_wp_error( $guard ) ) { return $guard; }
		if ( get_option( 'tkd_fo_agreed_reprice_lock_' . $order_id, false ) ) { return new WP_Error( 'invoice_busy', 'Зараз зберігаються товари. Дочекайтеся завершення та повторіть.' ); }
		if ( in_array( get_post_meta( $order_id, '_tkd_status', true ), array( 'shipped', 'cancelled', 'returned', 'refunded', 'unavailable' ), true ) || get_post_meta( $order_id, '_tkd_fo_historical_stock_reconciliation_v1', true ) ) { return new WP_Error( 'invoice_closed', 'Замовлення закрите. Новий рахунок не створено.' ); }
		if ( ! $rv_bank && ( ! is_callable( array( 'TKD_FO_Commerce', 'manager_terms_confirmed' ) ) || ! TKD_FO_Commerce::manager_terms_confirmed( $order_id ) ) ) {
			return new WP_Error( 'invoice_terms', 'Спочатку оберіть та підтвердьте продавця, оплату й доставку в замовленні. Рахунок не створено.' );
		}
		$seller = $rv_bank ? 'fop_rv' : TKD_FO_Commerce::invoice_seller_for_order( $order_id );
		if ( ! in_array( $seller, array( 'no_vat', 'fop_pm', 'fop_rv', 'fop_tp', 'fop_md', 'fop_eo', 'vat' ), true ) ) {
			return new WP_Error( 'invoice_seller', 'Оберіть продавця в замовленні. Рахунок не створено.' );
		}
		if ( class_exists( 'TKD_FO_Seller_Control' ) ) { $seller_gate = TKD_FO_Seller_Control::invoice_guard( $order_id, $seller, $rv_bank || $paid_liqpay || $wayforpay || $initial_bank ); if ( is_wp_error( $seller_gate ) ) { return $seller_gate; } }
		$invoice_bank = 'fop_md' === $seller ? 'md_privat' : ( ( $rv_bank || in_array( $seller, array( 'fop_pm', 'fop_tp', 'vat' ), true ) ) ? 'privat' : 'pumb' );
		if ( 'fop_eo' === $seller ) { $invoice_bank = 'bank_emeo'; }
		// This selection applies only to a new MD invoice. Existing invoices
		// already returned above keep their saved bank, even on a repeated click.
		if ( '' !== $bank_key ) {
			if ( 'fop_md' !== $seller || ! is_string( $bank_key ) || 'md_privat' !== $bank_key ) {
				return new WP_Error( 'invoice_bank', 'Для нового рахунку ФОП Михеди оберіть ПриватБанк. Райффайзен тимчасово приховано. Рахунок не створено.' );
			}
			$invoice_bank = $bank_key;
		}
		$items = TKD_FO_Orders::get_order_items( $order_id );
		if ( ! is_array( $items ) || ! $items ) { return new WP_Error( 'invoice_items', 'Спочатку збережіть товари та суму замовлення.' ); }

		if ( $seller === 'vat' ) {
			$vat_totals = self::calculate_totals( $items, $seller, (float) get_post_meta( $order_id, '_tkd_fo_order_discount', true ) );
			if ( (int) round( $vat_totals['total'] * 100 ) !== (int) round( TKD_FO_Payments::order_total( $order_id ) * 100 ) ) { return new WP_Error( 'invoice_vat_total', 'Підтвердьте погоджену суму з ПДВ у блоці продавця. Рахунок не створено.' ); }
		}

		$invoice_id = wp_insert_post( array( 'post_type' => 'tkd_invoice', 'post_status' => 'publish', 'post_title' => 'Чернетка рахунку' ) );
		if ( is_wp_error( $invoice_id ) || ! $invoice_id ) {
			return new WP_Error( 'invoice_create', 'Не вдалося створити рахунок.' );
		}
		$date   = wp_date( 'Y-m-d' );
		$number = 'vat' === $seller ? '' : self::next_no_vat_number( $date, $seller );
		$items  = TKD_FO_Orders::get_order_items( $order_id );
		$discount = (float) get_post_meta( $order_id, '_tkd_fo_order_discount', true );
		update_post_meta( $invoice_id, '_tkd_fo_order_id', $order_id );
		update_post_meta( $invoice_id, '_tkd_fo_seller_key', $seller );
		update_post_meta( $invoice_id, '_tkd_fo_bank_key', $invoice_bank );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_number', $number );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_date', $date );
		update_post_meta( $invoice_id, '_tkd_fo_delivery_date', $date );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_status', 'draft' );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_items', $items );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_discount', number_format( $discount, 2, '.', '' ) );
		update_post_meta( $invoice_id, '_tkd_fo_buyer_type', 'person' );
		update_post_meta( $invoice_id, '_tkd_fo_buyer_name', get_post_meta( $order_id, '_tkd_customer_name', true ) );
		update_post_meta( $invoice_id, '_tkd_fo_buyer_phone', get_post_meta( $order_id, '_tkd_customer_phone', true ) );
		update_post_meta( $invoice_id, '_tkd_fo_buyer_email', get_post_meta( $order_id, '_tkd_customer_email', true ) );
		update_post_meta( $invoice_id, '_tkd_fo_application', get_post_meta( $order_id, '_tkd_order_number', true ) );
		$totals = self::calculate_totals( $items, $seller, $discount );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_items_subtotal', number_format( $totals['items_subtotal'], 2, '.', '' ) );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_subtotal', number_format( $totals['subtotal'], 2, '.', '' ) );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_vat', number_format( $totals['vat'], 2, '.', '' ) );
		update_post_meta( $invoice_id, '_tkd_fo_invoice_total', number_format( $totals['total'], 2, '.', '' ) );
		update_post_meta( $order_id, '_tkd_fo_invoice_id', $invoice_id );
		self::register_order_invoice( $order_id, $invoice_id );
		wp_update_post( array( 'ID' => $invoice_id, 'post_title' => $number === '' ? 'Чернетка рахунку ТОВ — замовлення ' . $order_id : 'Рахунок ' . $number ) );
		TKD_FO_Orders::claim_responsibility( $order_id, 'Створено рахунок № ' . $number );
		return (int) $invoice_id;
		} finally { $wpdb->get_var( $wpdb->prepare( 'SELECT RELEASE_LOCK(%s)', $mutex ) ); }
	}

public static function manager_invoice_context( $order_id ) {
	global $wpdb;
	$order_id = absint( $order_id );
	$fail = static function( $message ) { return new WP_Error( 'invoice_context', $message ); };
	if ( ! $order_id || get_post_type( $order_id ) !== 'tkd_order' ) { return $fail( 'Замовлення не знайдено.' ); }
	$primary = get_post_meta( $order_id, '_tkd_fo_invoice_id', true );
	$stored = get_post_meta( $order_id, '_tkd_fo_invoice_ids', true );
	if ( $stored === '' ) { $stored = array(); }
	if ( ! is_array( $stored ) ) { return $fail( 'Пошкоджено перелік рахунків.' ); }
	if ( $primary !== '' && $primary !== '0' && $primary !== 0 ) { $stored[] = $primary; }
	foreach ( $stored as $value ) { if ( ! is_scalar( $value ) || ! preg_match( '/\A[1-9][0-9]*\z/D', (string) $value ) ) { return $fail( 'Некоректний зв’язок рахунку.' ); } }
	$found = get_posts( array( 'post_type' => 'tkd_invoice', 'post_status' => array_values( get_post_stati() ), 'posts_per_page' => -1, 'fields' => 'ids', 'cache_results' => false, 'meta_key' => '_tkd_fo_order_id', 'meta_value' => $order_id ) );
	if ( ! is_array( $found ) || $wpdb->last_error ) { return $fail( 'Не вдалося перевірити історію рахунків.' ); }
	$ids = array_values( array_unique( array_map( 'absint', array_merge( $stored, $found ) ) ) ); sort( $ids );
	$active = array(); $archived = array(); $revision = array();
	foreach ( $ids as $id ) {
		if ( get_post_type( $id ) !== 'tkd_invoice' || absint( get_post_meta( $id, '_tkd_fo_order_id', true ) ) !== $order_id ) { return $fail( 'Рахунок має неоднозначний зв’язок із замовленням.' ); }
		$status = (string) get_post_meta( $id, '_tkd_fo_invoice_status', true );
		$post_status = get_post_status( $id );
		if ( $status === 'cancelled' || $post_status === 'trash' ) { $archived[] = $id; } else { $active[] = $id; }
		$revision[$id] = array( $post_status, $status );
		foreach ( array( '_tkd_fo_seller_key', '_tkd_fo_invoice_items', '_tkd_fo_invoice_total', '_tkd_fo_invoice_discount', '_tkd_fo_split_invoice' ) as $key ) { $revision[$id][$key] = get_post_meta( $id, $key, true ); }
	}
	if ( count( $active ) > 1 ) { return $fail( 'Є кілька чинних рахунків. Для розподілу між ФОП використовуйте пакети документів.' ); }
	return array( 'active' => $active ? $active[0] : 0, 'archived' => $archived, 'all' => $ids, 'revision' => hash( 'sha256', serialize( $revision ) ) );
}

public static function manager_archive_guard( $invoice_id ) {
	global $wpdb;
	$id = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
	if ( ! $id || ! current_user_can( 'manage_tkd_felicity' ) || ! current_user_can( 'edit_post', $id ) || ! current_user_can( 'edit_post', $invoice_id ) ) { return new WP_Error( 'invoice_archive', 'Немає доступу до пов’язаного замовлення.' ); }
	$ctx = self::manager_invoice_context( $id ); if ( is_wp_error( $ctx ) ) { return $ctx; }
	if ( ! in_array( $invoice_id, $ctx['all'], true ) ) { return new WP_Error( 'invoice_archive', 'Рахунок не належить замовленню.' ); }
	$deliveries = get_posts( array( 'post_type'=>'tkd_delivery', 'post_status'=>array_values(get_post_stati()), 'posts_per_page'=>-1, 'fields'=>'ids', 'meta_query'=>array('relation'=>'OR',array('key'=>'_tkd_fo_delivery_order_id','value'=>$id),array('key'=>'_tkd_fo_delivery_invoice_id','value'=>$invoice_id)) ) );
	if ( ! is_array( $deliveries ) || $wpdb->last_error || $deliveries ) { return new WP_Error( 'invoice_archive', 'Є видаткова або її стан не підтверджений. Спочатку потрібно узгодити пакет відвантаження.' ); }
	return TKD_FO_Orders::editor_pricing_guard( $id, $ctx['active'], TKD_FO_Payments::order_total( $id ) );
}

public static function linked_invoice_ids_for_order( $order_id ) {
	$order_id = absint( $order_id );
	if ( ! $order_id ) {
		return array();
	}
	$primary = absint( get_post_meta( $order_id, '_tkd_fo_invoice_id', true ) );
	$stored  = get_post_meta( $order_id, '_tkd_fo_invoice_ids', true );
	$ids     = is_array( $stored ) ? array_map( 'absint', $stored ) : array();
	$found   = get_posts(
		array(
			'post_type'      => 'tkd_invoice',
			'post_status'    => 'any',
			'posts_per_page' => -1,
			'fields'         => 'ids',
			'meta_key'       => '_tkd_fo_order_id',
			'meta_value'     => $order_id,
			'orderby'        => 'ID',
			'order'          => 'ASC',
		)
	);
	$ids = array_values( array_unique( array_filter( array_merge( $primary ? array( $primary ) : array(), $ids, array_map( 'absint', $found ) ) ) ) );
	$ids = array_values(
		array_filter(
			$ids,
			static function ( $invoice_id ) use ( $order_id ) {
				return 'tkd_invoice' === get_post_type( $invoice_id )
					&& $order_id === absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
			}
		)
	);
	if ( $primary && in_array( $primary, $ids, true ) ) {
		$ids = array_values( array_diff( $ids, array( $primary ) ) );
		array_unshift( $ids, $primary );
	}
	return $ids;
}

private static function register_order_invoice( $order_id, $invoice_id ) {
	$order_id   = absint( $order_id );
	$invoice_id = absint( $invoice_id );
	if ( ! $order_id || ! $invoice_id ) {
		return;
	}
	$ids   = self::linked_invoice_ids_for_order( $order_id );
	$ids[] = $invoice_id;
	update_post_meta( $order_id, '_tkd_fo_invoice_ids', array_values( array_unique( array_map( 'absint', $ids ) ) ) );
}

private static function next_no_vat_number( $date, $seller = 'no_vat' ) {
	$seller = self::normalize_seller_key( $seller );
	$seller = 'vat' === $seller ? 'no_vat' : $seller;
	$year   = $date && strtotime( $date ) ? wp_date( 'Y', strtotime( $date ) ) : wp_date( 'Y' );
	$prefix = trim( (string) get_option( 'tkd_fo_invoice_prefix', '' ) );
	$key    = 'tkd_fo_invoice_sequence_' . $year;
	$next   = (int) get_option( $key, 0 ) + 1;
	do {
		$number = ( $prefix ? $prefix . '-' : '' ) . $year . '-' . str_pad( (string) $next, 4, '0', STR_PAD_LEFT );
		$next++;
	} while ( self::number_exists( $seller, $number, 0 ) );
	update_option( $key, $next - 1, false );
	return $number;
}

private static function normalize_seller_key( $seller_key ) {
	$seller_key = sanitize_key( (string) $seller_key );
	$profiles   = TKD_FO_DB::seller_profiles();
	return isset( $profiles[ $seller_key ] ) ? $seller_key : 'no_vat';
}

private static function number_exists( $seller, $number, $exclude_id ) {
	$query = new WP_Query(
		array(
			'post_type'      => 'tkd_invoice',
			'post_status'    => 'any',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'post__not_in'   => $exclude_id ? array( absint( $exclude_id ) ) : array(),
			'meta_query'     => array(
				'relation' => 'AND',
				array( 'key' => '_tkd_fo_seller_key', 'value' => $seller ),
				array( 'key' => '_tkd_fo_invoice_number', 'value' => $number ),
			),
		)
	);
	return $query->have_posts();
}

