	);
}

public static function get_responsibility( $order_id ) {
	$order_id = absint( $order_id );
	if ( ! $order_id || 'tkd_order' !== get_post_type( $order_id ) ) {
		return array();
	}
	$record = get_option( 'tkd_fo_order_responsibility_' . $order_id, false );
	if ( false !== $record ) {
		return is_array( $record ) && ! empty( $record['user_id'] ) && ! empty( $record['user_name'] ) ? $record : array();
	}

	$manager_id = absint( get_post_meta( $order_id, '_tkd_fo_reservation_manager_id', true ) );
	if ( ! $manager_id || ! self::reservation_manager_is_manual( $order_id, $manager_id ) ) {
		return array();
	}
	$user = get_userdata( $manager_id );
	if ( ! $user ) {
		return array();
	}
	$record = array(
		'user_id'   => $manager_id,
		'user_name' => sanitize_text_field( $user->display_name ? $user->display_name : $user->user_login ),
		'time'      => 0,
		'reason'    => 'Раніше призначений відповідальний за бронь',
		'source'    => 'legacy_manual',
	);
	$log = get_post_meta( $order_id, '_tkd_fo_reservation_log', true );
	foreach ( is_array( $log ) ? $log : array() as $entry ) {
		if ( ! is_array( $entry ) ) {
			continue;
		}
		if ( $manager_id === absint( isset( $entry['user_id'] ) ? $entry['user_id'] : 0 ) && ! empty( $entry['time'] ) && ( ! $record['time'] || absint( $entry['time'] ) < $record['time'] ) ) {
			$record['time'] = absint( $entry['time'] );
			$record['reason'] = ! empty( $entry['action'] ) ? sanitize_text_field( $entry['action'] ) : $record['reason'];
		}
	}
	return $record;
}

private static function responsibility_context_is_manual( $order_id ) {
	foreach ( array( 'DOING_CRON', 'DOING_AUTOSAVE', 'REST_REQUEST', 'WP_CLI' ) as $constant ) {
		if ( defined( $constant ) && constant( $constant ) ) {
			return false;
		}
	}
	return $order_id && is_admin() && is_user_logged_in() && 'tkd_order' === get_post_type( $order_id )
		&& ! wp_is_post_revision( $order_id ) && ! wp_is_post_autosave( $order_id )
		&& current_user_can( 'manage_tkd_felicity' ) && current_user_can( 'edit_post', $order_id );
}

public static function claim_responsibility( $order_id, $reason ) {
	$lock = TKD_FO_Order_Lifecycle::owner_lock(); if ( ! $lock ) { return array(); }
	try { TKD_FO_Order_Lifecycle::prepare_link( absint( $order_id ) ); return self::claim_responsibility_locked( $order_id, $reason ); }
	finally { TKD_FO_Order_Lifecycle::unlock( $lock ); }
}

private static function claim_responsibility_locked( $order_id, $reason ) {
	global $wpdb;
	$order_id = absint( $order_id );
	if ( ! self::responsibility_context_is_manual( $order_id ) ) {
		return array();
	}
	$option = 'tkd_fo_order_responsibility_' . $order_id;
	$stored = get_option( $option, false );
	// Imported inquiries deliberately start with an empty ownership sentinel.
	// It means unassigned, not an existing owner. Preserve every non-empty record.
	if ( false !== $stored && array() !== $stored ) {
		return self::get_responsibility( $order_id );
	}
	$record = self::get_responsibility( $order_id );
	if ( ! $record ) {
		$user = get_userdata( get_current_user_id() );
		if ( ! $user ) {
			return array();
		}
		$record = array(
			'user_id'   => (int) $user->ID,
			'user_name' => sanitize_text_field( $user->display_name ? $user->display_name : $user->user_login ),
			'time'      => time(),
			'reason'    => sanitize_text_field( $reason ),
			'source'    => 'manual_action',
		);
	}
	// Both paths are atomic: concurrent managers cannot replace the first owner.
	$inserted = array() === $stored
