	$map = array( 'fop_pm' => 'fop_pm', 'no_vat' => 'fop_iy', 'fop_rv' => 'fop_rv', 'vat' => 'ti_group' ); $rows = array(); $totals = array(); $sum = 0;
	$ids = self::linked( 'tkd_invoice', '_tkd_fo_order_id', $order );
	$cached = $o['_tkd_fo_invoice_ids']; if ( $cached === '' ) { $cached = array(); } if ( ! is_array( $cached ) ) { self::fail( 'Пошкоджено перелік рахунків.' ); }
	if ( $o['_tkd_fo_invoice_id'] !== '' ) { $cached[] = $o['_tkd_fo_invoice_id']; }
	foreach ( $cached as $other ) { if ( ! self::id( $other ) || ! in_array( (int) $other, $ids, true ) ) { self::fail( 'Є сторонній або втрачений рахунок; потрібна звірка.' ); } }
	foreach ( $ids as $other ) {
