		if ( ! self::active_post( $other, 'tkd_invoice' ) || ! in_array( $r['_tkd_fo_invoice_status'], array( 'draft', 'issued', 'paid' ), true ) ) { self::fail( 'Пов’язаний рахунок недоступний або має непідтримуваний статус.' ); }
