		if ( (int) round( $products * 100 ) !== $v['items_subtotal'] || $v['discount'] > $v['items_subtotal'] || $v['subtotal'] !== $v['items_subtotal'] - $v['discount'] || $v['total'] !== $v['subtotal'] + $v['vat'] || $v['total'] <= 0 || ( $seller !== 'vat' && $v['vat'] !== 0 ) ) { self::fail( 'Ціни, кількості, знижка й сума рахунку не узгоджені.' ); }
		$rows[$other] = $r; $sum += $v['total']; $totals[$map[$seller]] = ( $totals[$map[$seller]] ?? 0 ) + $v['total'];
	}
	if ( ! isset( $rows[$invoice] ) || $d['_tkd_fo_delivery_seller_key'] !== $rows[$invoice]['_tkd_fo_seller_key'] ) { self::fail( 'Видаткова не відповідає чинному рахунку й продавцю.' ); }
	$total = $o['_tkd_confirmed_amount'] === '' ? 0 : self::money( $o['_tkd_confirmed_amount'] ); if ( $total === 0 ) { $total = self::money( $o['_tkd_client_total'] ); }
	if ( $total <= 0 || $sum !== $total ) { self::fail( 'Повний пакет рахунків не збігається із сумою замовлення.' ); }
	$items = $d['_tkd_fo_delivery_items']; $source = $rows[$invoice]['_tkd_fo_invoice_items']; $indices = array(); $full = is_array( $items ) && count( $items ) === count( $source );
	if ( ! is_array( $items ) || ! $items ) { self::fail( 'Немає збережених товарів видаткової.' ); }
	foreach ( $items as $line ) {
		$index = is_array( $line ) ? ( $line['source_index'] ?? null ) : null;
		if ( ! is_int( $index ) || isset( $indices[$index] ) || ! isset( $source[$index] ) ) { self::fail( 'Видаткова має сторонню або повторну позицію.' ); }
		$original = $source[$index]; foreach ( array( 'sku', 'name', 'unit' ) as $k ) { if ( ( $line[$k] ?? null ) !== $original[$k] ) { self::fail( 'Товар видаткової не збігається з рахунком.' ); } }
		$q = self::quantity( $line['quantity'] ?? null ); $sq = self::quantity( $original['quantity'] );
