}

private static function bank_method( $method ) {
	if ( ! is_string( $method ) ) { return false; }
	$method = trim( $method );
	if ( in_array( strtolower( $method ), array( '', 'bank', 'bank_transfer', 'invoice', 'iban', 'cashless' ), true ) ) { return true; }
	return preg_match( '/\AБезготівкова оплата за рахунком \(IBAN\)(?: після підтвердження наявності)?\z/iu', $method ) === 1;
}

public static function manager_iban_terms( $order, $seller ) {
	if ( ! in_array( $seller, array( 'fop_pm', 'no_vat', 'fop_rv' ), true ) ) { return false; }
	if ( get_post_meta( $order, '_tkd_fo_checkout_seller_key', true ) !== $seller ) { return false; }
	$method = get_post_meta( $order, '_tkd_payment_method', true );
	if ( ! is_string( $method ) || trim( $method ) === '' || ! self::bank_method( $method ) ) { return false; }
	$shipping = get_post_meta( $order, '_tkd_np_delivery_method', true );
	if ( ! in_array( $shipping, array( 'pickup', 'nova_warehouse', 'nova_locker', 'nova_courier' ), true ) ) { return false; }
	$type = get_post_meta( $order, '_tkd_np_payment_type', true );
	$cod = get_post_meta( $order, '_tkd_np_cod_amount', true );
	return in_array( $type, array( '', 'prepaid' ), true ) && ( $cod === '' || ( is_numeric( $cod ) && (float) $cod === 0.0 ) );
}

