			if ( ! is_array( $r ) || ! in_array( $r['state'] ?? '', array( 'ok', 'ready', 'blocked' ), true ) || ! self::text( $r['message'] ?? null ) || ! is_bool( $r['auto_eligible'] ?? null ) || ! is_string( $r['fingerprint'] ?? null ) || ! preg_match( '/^[0-9a-f]{64}$/D', $r['fingerprint'] ) || ! is_string( $r['fiscal_number'] ?? null ) ) { self::fail( 'Модуль фіскалізації не повернув перевіреного результату. Передача заблокована.' ); }
			if ( $r['state'] === 'ok' && ( ! preg_match( '/^[1-9][0-9]{0,19}$/D', $r['fiscal_number'] ) || ! in_array( $r['source'] ?? '', array( 'parcel', 'external' ), true ) ) ) { self::fail( 'Немає підтвердженого номера й джерела фіскального чека.' ); }
			if ( $r['state'] === 'ready' && ( $r['auto_eligible'] !== true || $r['fiscal_number'] !== '' || ( $r['source'] ?? '' ) !== 'none' ) ) { self::fail( 'Готовність фіскалізації не підтверджена.' ); }
			if ( $legacy_api !== null && $r['state'] !== 'blocked' ) {
				if ( $r['state'] !== 'ok' || ( $r['source'] ?? '' ) !== 'external' || $r['fiscal_number'] !== ( $legacy_api['fiscal_number'] ?? null ) || PML_External_Receipt::get( $c['order'] ) !== $legacy_api || ! self::db_ok() ) {
					return self::result( 'blocked', 'Історичний продавець підтверджується лише чинною прив’язкою вже створеного API-чека. Новий чек не дозволено; потрібна звірка.', $fingerprint, '', $c['order'] );
				}
			}
			return self::result( $r['state'], $r['message'], hash( 'sha256', $fingerprint . '|' . $r['fingerprint'] ), $r['fiscal_number'], $c['order'] );
		} catch ( Throwable $error ) { return self::result( 'blocked', $error instanceof TKD_Sales_Fiscal_Gate_Error ? $error->getMessage() : 'Перевірку фіскального чека перервано. Проведення й передача заблоковані до звірки.' ); }
	}

