private static function dispatch_status( $delivery_id, $list_read = false ) {
	$np = self::np_dispatch( $delivery_id ); $class = $np ? 'TKD_NP_Dispatch' : 'TKD_FO_Dispatch';
	$out = array( 'enabled' => false, 'mode' => $np ? 'np' : '', 'state' => '', 'blockers' => array(), 'url' => '' );
	if ( ! is_callable( array( $class, 'status' ) ) ) { if ( $np ) { $out['blockers'][] = 'Модуль контролю Нової пошти недоступний. Завдання залишається в черзі; автоматичного переходу на самовивіз немає.'; } return $out; }
	try {
		$data = $list_read && $np && is_callable( array( $class, 'status_for_list' ) )
			? $class::status_for_list( $delivery_id ) : $class::status( $delivery_id );
		if ( is_array( $data ) ) {
			$out['enabled'] = true === ( $data['enabled'] ?? false );
			foreach ( array( 'mode', 'state' ) as $key ) { if ( isset( $data[$key] ) && is_string( $data[$key] ) ) { $out[$key] = sanitize_key( $data[$key] ); } }
			foreach ( is_array( $data['blockers'] ?? null ) ? $data['blockers'] : array() as $message ) { if ( is_string( $message ) ) { $out['blockers'][] = sanitize_text_field( $message ); } }
		}
		if ( $np && ( ! is_array( $data ) || ! is_array( $data['blockers'] ?? null ) || count( $out['blockers'] ) !== count( $data['blockers'] ) ) ) { $out['enabled'] = false; $out['blockers'][] = 'Відповідь контролю Нової пошти потребує перевірки.'; }
		if ( $np && ( $out['mode'] !== 'np' || ! in_array( $out['state'], array( 'preparing', 'awaiting_handover', 'handed_over' ), true ) ) ) { $out['enabled'] = false; $out['mode'] = 'np'; $out['state'] = ''; $out['blockers'][] = 'Стан контролю Нової пошти не підтверджено.'; }
		if ( $np && $out['blockers'] && $out['state'] === 'handed_over' ) { $out['state'] = 'awaiting_handover'; }
		if ( is_callable( array( $class, 'url' ) ) ) {
			$url = $class::url( $delivery_id );
			// The core owns this authenticated page; do not accept arbitrary protocols/hosts.
			$base = admin_url( 'admin-post.php' );
			$expected = add_query_arg( array( 'action' => $np ? 'tkd_np_dispatch' : 'tkd_fo_dispatch', 'delivery_id' => (int) $delivery_id ), $base );
			if ( is_string( $url ) && $url === $expected ) { $out['url'] = $url; }
		}
	} catch ( Throwable $error ) {
		$out = array( 'enabled' => false, 'mode' => $np ? 'np' : '', 'state' => '', 'blockers' => array( 'Контроль фізичної видачі зараз недоступний. Потрібна перевірка менеджера.' ), 'url' => '' );
	}
	return $out;
}

