private static function revision_data( $delivery_id, $without_serials = false ) {
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$items = self::items( $delivery_id );
	// The office may adopt a new revision only when nothing except scanner state/SN changed.
	if ( $without_serials ) { foreach ( $items as &$item ) { unset( $item['serial_numbers'] ); } unset( $item ); }
	$data = array( 'items' => $items, 'invoice_id' => $invoice_id );
	foreach ( array( 'order_id', 'number', 'date', 'status', 'seller_key', 'place', 'receiver', 'payer', 'contract', 'application' ) as $field ) {
		$data[ 'delivery_' . $field ] = get_post_meta( $delivery_id, '_tkd_fo_delivery_' . $field, true );
	}
	foreach ( array( '_tkd_fo_invoice_items', '_tkd_fo_invoice_status', '_tkd_fo_invoice_discount', '_tkd_fo_seller_key', '_tkd_fo_order_id' ) as $field ) {
		$data[ $field ] = get_post_meta( $invoice_id, $field, true );
	}
	if ( ! $without_serials ) { $data['task'] = self::task_state( $delivery_id ); }
	return $data;
}

public static function office_revision( $delivery_id ) {
	return hash( 'sha256', serialize( self::revision_data( $delivery_id ) ) );
}

public static function begin_office_save( $delivery_id, $posted_revision ) {
	$lease = self::acquire();
	if ( is_wp_error( $lease ) ) { return $lease; }
	try {
		self::fresh( $delivery_id );
		if ( is_string( $posted_revision ) && hash_equals( self::office_revision( $delivery_id ), $posted_revision ) ) { return $lease; }
	} catch ( Throwable $error ) {
		self::release( $lease );
		return self::error( 'read_failed', 'Не вдалося перевірити актуальність видаткової. Зміни заблоковано.', 503 );
	}
	self::release( $lease );
	return self::error( 'stale_revision', 'Видаткова або складське завдання змінилися. Оновіть сторінку перед збереженням; серійні номери не перезаписано.' );
}

private static function serials( $value ) {
	$out = array();
	foreach ( preg_split( '/[\r\n,;]+/u', (string) $value ) as $serial ) {
		$serial = trim( $serial );
		if ( '' !== $serial ) { $out[] = $serial; }
	}
	return $out;
}

private static function canonical( $serial ) {
	return strtoupper( preg_replace( '/[\x09-\x0D\x20]+/', '', trim( (string) $serial ) ) );
}

private static function valid_serial( $serial, $item ) {
	if ( strtoupper( trim( (string) ( $item['sku'] ?? '' ) ) ) === 'SPI4862V100-500P' ) {
		return (bool) preg_match( '/^GL-\d{10}-\d{5}-B\d{2}$/D', $serial );
	}
	return (bool) preg_match( '/^\d{18}$/D', $serial );
}

private static function line_map( $items ) {
	$map = array();
	foreach ( $items as $key => $item ) {
		if ( ! is_array( $item ) || ! isset( $item['source_index'] ) || ! preg_match( '/^\d+$/D', (string) $item['source_index'] ) || isset( $map[ (int) $item['source_index'] ] ) ) { return self::error( 'invalid_lines', 'Позиції видаткової потребують перевірки менеджером.' ); }
		$map[ (int) $item['source_index'] ] = $key;
	}
	return $map;
}

private static function check_invoice( $delivery_id, $items ) {
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$source = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	$map = self::line_map( $items );
	if ( is_wp_error( $map ) ) { return $map; }
	foreach ( $map as $index => $key ) {
		$item = $items[ $key ];
		$row = is_array( $source ) && isset( $source[ $index ] ) ? $source[ $index ] : null;
		if ( ! is_array( $row ) || (string) ( $row['sku'] ?? '' ) !== (string) ( $item['sku'] ?? '' ) || (string) ( $row['unit'] ?? '' ) !== (string) ( $item['unit'] ?? '' ) || ( empty( $item['sku'] ) && (string) ( $item['name'] ?? '' ) !== (string) ( $row['name'] ?? '' ) ) ) { return self::error( 'invoice_changed', 'Позиції рахунку змінилися. Потрібна перевірка менеджером перед скануванням.' ); }
		if ( (float) ( $item['quantity'] ?? 0 ) <= 0 || (float) $item['quantity'] > (float) ( $row['quantity'] ?? 0 ) ) { return self::error( 'invoice_changed', 'Кількість у видатковій не відповідає рахунку. Потрібна перевірка менеджером.' ); }
	}
	return true;
}

private static function source_guard( $delivery_id ) {
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$source = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	$rows = array();
	foreach ( is_array( $source ) ? $source : array() as $index => $item ) {
		$rows[ $index ] = array( (string) ( $item['sku'] ?? '' ), (string) ( $item['name'] ?? '' ), (string) ( $item['unit'] ?? '' ), (float) ( $item['quantity'] ?? 0 ) );
	}
	return hash( 'sha256', serialize( array( $invoice_id, $rows ) ) );
}

private static function task_source_valid( $delivery_id, $task ) {
	return isset( $task['source_guard'] ) && is_string( $task['source_guard'] ) && hash_equals( self::source_guard( $delivery_id ), $task['source_guard'] );
}

private static function duplicate_check( $delivery_id, $items ) {
	$wanted = array();
	foreach ( $items as $item ) {
		foreach ( self::serials( $item['serial_numbers'] ?? '' ) as $serial ) {
			$key = self::canonical( $serial );
			if ( isset( $wanted[ $key ] ) ) { return self::error( 'duplicate_serial', 'Цей серійний номер уже є в іншій позиції цієї видаткової.' ); }
			$wanted[ $key ] = true;
		}
	}
	if ( ! $wanted ) { return true; }
	$ids = get_posts( array( 'post_type' => 'tkd_delivery', 'post_status' => array( 'publish', 'draft', 'pending', 'private', 'future' ), 'posts_per_page' => -1, 'fields' => 'ids', 'post__not_in' => array( $delivery_id ), 'no_found_rows' => true ) );
	foreach ( $ids as $id ) {
		wp_cache_delete( $id, 'post_meta' );
		if ( 'cancelled' === get_post_meta( $id, '_tkd_fo_delivery_status', true ) || 'trash' === get_post_status( $id ) ) { continue; }
		foreach ( self::items( $id ) as $item ) {
			foreach ( self::serials( $item['serial_numbers'] ?? '' ) as $serial ) {
				if ( isset( $wanted[ self::canonical( $serial ) ] ) ) { return self::error( 'duplicate_serial', 'Серійний номер уже записано в іншій активній або виданій накладній. Зверніться до менеджера.' ); }
			}
		}
	}
	return true;
}

private static function required_complete( $items, $required ) {
	$map = self::line_map( $items );
	if ( is_wp_error( $map ) ) { return $map; }
	foreach ( $required as $index ) {
		if ( ! isset( $map[ $index ] ) ) { return self::error( 'task_changed', 'Позиції складського завдання змінилися. Потрібна перевірка менеджера.' ); }
		$item = $items[ $map[ $index ] ];
		$qty = (float) ( $item['quantity'] ?? 0 );
		$serials = self::serials( $item['serial_numbers'] ?? '' );
		if ( ! self::serial_target( $item ) || count( $serials ) !== self::serial_target( $item ) ) { return self::error( 'incomplete', 'Запишіть по одному серійному номеру на кожну одиницю обов’язкових позицій.' ); }
		foreach ( $serials as $serial ) { if ( ! self::valid_serial( $serial, $item ) ) { return self::error( 'invalid_serial', 'Номер не відповідає формату SN вибраної моделі. Для Green потрібен повний GL-…-…-B…, для Felicity — 18 цифр.' ); } }
	}
	return true;
}

private static function signature( $items ) {
	$rows = array();
	foreach ( $items as $item ) {
		$rows[] = array( (int) ( $item['source_index'] ?? -1 ), (string) ( $item['sku'] ?? '' ), (string) ( $item['name'] ?? '' ), (string) ( $item['unit'] ?? '' ), (float) ( $item['quantity'] ?? 0 ), self::serials( $item['serial_numbers'] ?? '' ) );
	}
	return serialize( $rows );
}

public static function manager_release_plan( $id ) {
	if ( ! is_int( $id ) || $id <= 0 || ! self::allowed() || ! self::manager() || ! current_user_can( 'edit_post', $id ) || ! self::available() || ! self::np_method( $id ) ) { return self::error( 'release_access', 'Підготовка доступна менеджеру для видаткової Нової пошти.' ); }
	self::fresh( $id ); $access = self::access_task( $id ); if ( is_wp_error( $access ) ) { return $access; }
	$order = (int) get_post_meta( $id, '_tkd_fo_delivery_order_id', true );
	if ( metadata_exists( 'post', $id, '_tkd_fo_historical_stock_reconciliation_v1' ) || metadata_exists( 'post', $order, '_tkd_fo_historical_stock_reconciliation_v1' ) ) { return self::error( 'release_history', 'Історична звірка не входить у нове проведення. Повторне списання заблоковано.' ); }
	foreach ( array( '_tkd_fo_delivery_stock_processed_at', '_tkd_fo_delivery_handover_post_v1', '_tkd_fo_delivery_previous_order_status', '_tkd_fo_dispatch_v1', '_tkd_fo_historical_stock_reconciliation_v1' ) as $key ) {
		if ( get_post_meta( $id, $key, true ) !== '' ) { return self::error( 'release_history', 'Є попереднє проведення або інший контроль передачі. Потрібна звірка; повторного списання немає.' ); }
	}
	$journal = get_post_meta( $id, '_tkd_fo_delivery_stock_journal', true );
	if ( $journal !== '' && $journal !== array() ) { return self::error( 'release_history', 'Видаткова вже має журнал списання. Потрібна звірка.' ); }
	$raw = get_post_meta( $id, self::TASK_META, true ); $task = self::task_state( $id );
	if ( $raw !== '' && ( ! is_array( $raw ) || ! self::active( $task ) || ! self::task_source_valid( $id, $task ) || ! is_array( $task['required_source_indices'] ?? null ) || ( isset( $task['audit'] ) && ! is_array( $task['audit'] ) ) ) ) { return self::error( 'release_task', 'Попереднє складське завдання скасоване або його товари змінилися. Потрібна звірка.' ); }
	if ( ! in_array( $task['dispatch_required'] ?? null, array( null, 0, 1 ), true ) || ! in_array( $task['dispatch_mode'] ?? '', array( '', 'np' ), true ) ) { return self::error( 'release_route', 'Завдання має інший контроль передачі.' ); }
	$items = self::items( $id ); if ( ! $items ) { return self::error( 'release_items', 'Спочатку збережіть товари видаткової.' ); }
	$check = self::check_invoice( $id, $items ); if ( is_wp_error( $check ) ) { return $check; }
	$required = $task['required_source_indices'] ?? array();
	foreach ( $items as $item ) {
		$index = $item['source_index'] ?? null; $sku = strtoupper( trim( (string) ( $item['sku'] ?? '' ) ) );
		if ( ! is_int( $index ) || $index < 0 ) { return self::error( 'release_items', 'Рядки видаткової потребують повторного збереження.' ); }
		// Only these known cable sets have no serial number. Other equipment must have its saved SN.
		$no_serial = in_array( $sku, array( 'AWG3-CU-35-1M-180C', 'AWG4-CU-25-1M-180C', '1000598' ), true );
		if ( ! $no_serial || self::serials( $item['serial_numbers'] ?? '' ) ) { $required[] = $index; }
	}
	$required = array_values( array_unique( $required, SORT_REGULAR ) );
	$check = self::required_complete( $items, $required ); if ( is_wp_error( $check ) ) { return $check; }
	$check = self::duplicate_check( $id, $items ); if ( is_wp_error( $check ) ) { return $check; }
	$assignee = $task['assignee_id'] ?? get_current_user_id(); $user = is_int( $assignee ) && $assignee > 0 ? get_userdata( $assignee ) : false;
	if ( ! $user || ( ! user_can( $user, self::CAPABILITY ) && ! user_can( $user, 'manage_tkd_felicity' ) && ! user_can( $user, 'manage_options' ) ) ) { return self::error( 'release_assignee', 'Працівник попереднього складського завдання недоступний.' ); }
	$task['assignee_id'] = $assignee; $task['state'] = 'ready'; $task['required_source_indices'] = $required;
	$task['source_guard'] = self::source_guard( $id ); $task['dispatch_required'] = 1; $task['dispatch_mode'] = 'np';
	$task['manager_release_v1'] = true;
	return array( 'task' => $task, 'revision' => self::office_revision( $id ) );
}

public static function prepare_saved_for_release( $id, $revision ) {
	if ( null === self::$lease || ( $_SERVER['REQUEST_METHOD'] ?? '' ) !== 'POST' || ( $_POST['command'] ?? '' ) !== 'prepare_saved' || ! is_string( $_POST['tkd_release_nonce'] ?? null ) || ! wp_verify_nonce( wp_unslash( $_POST['tkd_release_nonce'] ), 'tkd_sales_release_' . $id ) ) { return self::error( 'release_command', 'Потрібне натискання «Провести видаткову» менеджером.' ); }
	$plan = self::manager_release_plan( $id ); if ( is_wp_error( $plan ) ) { return $plan; }
	if ( ! is_string( $revision ) || ! hash_equals( $plan['revision'], $revision ) ) { return self::error( 'release_stale', 'Складські дані змінилися. Оновіть видаткову.' ); }
	$old = get_post_meta( $id, self::TASK_META, true ); $task = $plan['task'];
	if ( $old === '' ) { $task['assigned_by'] = get_current_user_id(); $task['assigned_at'] = current_time( 'mysql', true ); $task['events'] = array(); }
	self::audit( $task, 'manager_release_ready', array( 'source' => 'saved_delivery', 'required_source_indices' => $task['required_source_indices'] ) );
	$ok = $old === '' ? add_post_meta( $id, self::TASK_META, wp_slash( $task ), true ) : update_post_meta( $id, self::TASK_META, wp_slash( $task ), $old );
