public static function validate_office_change( $delivery_id, $items, $target_status ) {
	if ( null === self::$lease ) { return self::error( 'lock_required', 'Не вдалося захистити зміну видаткової. Оновіть сторінку.' ); }
	if ( 'cancelled' === $target_status ) { return true; }
	$task = self::task_state( $delivery_id );
	if ( 'issued' === $target_status && ( 1 === ( $task['dispatch_required'] ?? 0 ) || self::np_dispatch( $delivery_id ) ) && ! self::dispatch_status( $delivery_id )['enabled'] ) {
		return self::error( 'dispatch_unavailable', 'Контроль фізичної видачі цього завдання не ввімкнено або недоступний. Менеджер має перевірити його перед проведенням видаткової.' );
	}
	if ( self::active( $task ) ) {
		if ( ! self::task_source_valid( $delivery_id, $task ) ) { return self::error( 'task_source_changed', 'Рахунок змінився після призначення завдання. Скасуйте завдання, перевірте видаткову та призначте його повторно.' ); }
		if ( self::signature( self::items( $delivery_id ) ) !== self::signature( $items ) ) { return self::error( 'task_locked', 'Складське завдання активне. Для зміни позицій або серійних номерів скасуйте завдання; для виправлення скану відкрийте збирання повторно.' ); }
		if ( 'issued' === $target_status ) {
			if ( 'ready' !== $task['state'] ) { return self::error( 'not_ready', 'Склад ще збирає серійні номери. Проведення доступне після готовності завдання.' ); }
			$complete = self::required_complete( $items, $task['required_source_indices'] ?? array() );
			if ( is_wp_error( $complete ) ) { return $complete; }
		}
	}
	return self::duplicate_check( $delivery_id, $items );
}

private static function access_task( $delivery_id, $draft_only = true ) {
	if ( ! $delivery_id || 'tkd_delivery' !== get_post_type( $delivery_id ) || 'trash' === get_post_status( $delivery_id ) ) { return self::error( 'not_found', 'Завдання не знайдено.', 404 ); }
