private static function lock() {
	global $wpdb;
	$name = 'tkd_ws_' . substr( hash( 'sha256', ( defined( 'DB_NAME' ) ? DB_NAME : '' ) . '|' . $wpdb->prefix . '|' . ( function_exists( 'get_current_blog_id' ) ? get_current_blog_id() : 1 ) ), 0, 48 );
	return '1' === (string) $wpdb->get_var( $wpdb->prepare( 'SELECT GET_LOCK(%s,0)', $name ) ) ? $name : self::error( 'Інша складська дія виконується або захист змін недоступний.' );
