private static function save( $id, $old, $new ) {
	if ( ( $new['state'] ?? '' ) === 'handed_over' && ( $old['state'] ?? '' ) !== 'handed_over' ) {
		$c = self::context( $id );
		if ( ! is_wp_error( $c ) && is_string( $new['fingerprint'] ?? null ) && hash_equals( $new['fingerprint'], self::fingerprint( $c ) ) ) { $new['completed_physical_v1'] = self::completed_proof( $new, $c ); }
	}
	$ok = $old ? update_post_meta( $id, self::META, wp_slash( $new ), $old ) : add_post_meta( $id, self::META, wp_slash( $new ), true );
	wp_cache_delete( $id, 'post_meta' );
	return $ok && self::record( $id ) === $new ? true : self::error( 'Зміни не підтверджено. Оновіть сторінку; повторну передачу не підтверджуйте навмання.' );
