private static function canonical_phone( $phone ) {
	if ( ! is_string( $phone ) || ! preg_match( '/\A[+0-9 ()-]+\z/D', $phone ) ) { return ''; }
	$phone = preg_replace( '/[ ()-]/', '', $phone ); if ( preg_match( '/\A0[1-9][0-9]{8}\z/D', $phone ) ) { $phone = '38' . $phone; }
	return preg_match( '/\A\+?380[1-9][0-9]{8}\z/D', $phone ) ? ltrim( $phone, '+' ) : '';
}

private static function quantity( $value ) {
	if ( ! is_numeric( $value ) || ! is_finite( (float) $value ) || (float) $value <= 0 || (float) $value !== round( (float) $value, 3 ) ) { return null; }
	return floor( (float) $value ) === (float) $value ? (int) $value : (float) $value;
}

private static function financial( $order, $invoice, $seller ) {
	$f = array( 'blocker' => '', 'ledger' => get_post_meta( $order, '_tkd_fo_payments', true ), 'invoice' => array(), 'order_meta' => array(), 'allocation' => array() );
	foreach ( array( '_tkd_fo_invoice_status', '_tkd_fo_invoice_items', '_tkd_fo_invoice_total', '_tkd_fo_invoice_discount', '_tkd_fo_invoice_items_subtotal' ) as $key ) { $f['invoice'][$key] = get_post_meta( $invoice, $key, true ); }
	foreach ( array( '_tkd_prepayment_received', '_tkd_order_total', '_tkd_fo_agreed_total', '_tkd_fo_invoice_split_done', '_pml_cashalot_receipt', '_pml_cashalot_return', '_tkd_fo_payparts_receipt_required', '_tkd_liqpay_last_status', '_tkd_payparts_payment_state' ) as $key ) { $f['order_meta'][$key] = get_post_meta( $order, $key, true ); }
	if ( ! is_callable( array( 'TKD_FO_Payments', 'seller_allocation' ) ) || ! is_callable( array( 'TKD_FO_Payments', 'order_total' ) ) ) { $f['blocker'] = 'Перевірка оплат недоступна. Видачу заблоковано.'; return $f; }
	$f['order_total'] = TKD_FO_Payments::order_total( $order ); $f['allocation'] = TKD_FO_Payments::seller_allocation( $order );
	$credit = is_callable( array( 'TKD_FO_Deferred_Payment', 'authorization' ) ) ? TKD_FO_Deferred_Payment::authorization( $order ) : null;
	$deferred = is_array( $credit ) && $credit['terms']['seller'] === $seller && $credit['terms']['total_cents'] === (int) round( (float) $f['order_total'] * 100 ) && is_array( $f['allocation'] ) && count( $f['allocation'] ) === 1;
	$manager_bank = is_callable( array( 'TKD_Sales_Fiscal_Gate', 'manager_iban_terms' ) ) && TKD_Sales_Fiscal_Gate::manager_iban_terms( $order, $seller );
	$payment_timing_allowed = $deferred || $manager_bank;
	if ( $manager_bank && $f['ledger'] === '' ) { $f['ledger'] = array(); }
	if ( $deferred ) { $f['order_meta']['_tkd_fo_deferred_payment_v1'] = $credit; if ( $f['ledger'] === '' ) { $f['ledger'] = array(); } }
	$total = 0; $ids = array();
	if ( ! is_array( $f['ledger'] ) || ( ! $f['ledger'] && ! $payment_timing_allowed ) ) { $f['blocker'] = 'Потрібен підтверджений журнал оплат або збережені умови прямої IBAN-оплати.'; return $f; }
