		if ( $row['status'] === 'void' ) { continue; }
		if ( ! is_string( $row['id'] ?? null ) || $row['id'] === '' || isset( $ids[$row['id']] ) || ! is_numeric( $row['amount'] ?? null ) || ! is_finite( (float) $row['amount'] ) || (float) $row['amount'] <= 0 || empty( $row['recipient_key'] ) ) { $f['blocker'] = 'Оплати неповні, повторні або не прив’язані до продавця.'; return $f; }
		$ids[$row['id']] = true; $total += (float) $row['amount'];
	}
	$allocation = is_array( $f['allocation'] ) ? ( $f['allocation'][$seller] ?? array() ) : array(); $invoice_total = $f['invoice']['_tkd_fo_invoice_total'];
	if ( ! is_array( $allocation ) ) { $allocation = array(); }
	if ( ! is_numeric( $f['order_total'] ) || ! is_finite( (float) $f['order_total'] ) || (float) $f['order_total'] <= 0 || ( ! $payment_timing_allowed && round( $total, 2 ) < round( (float) $f['order_total'], 2 ) )
		|| ! is_numeric( $invoice_total ) || ! is_finite( (float) $invoice_total ) || (float) $invoice_total <= 0 || $f['invoice']['_tkd_fo_invoice_status'] === 'cancelled'
		|| ! is_array( $f['invoice']['_tkd_fo_invoice_items'] ) || ! $f['invoice']['_tkd_fo_invoice_items'] || ! is_array( $allocation['invoice_ids'] ?? null ) || ! in_array( $invoice, array_map( 'intval', $allocation['invoice_ids'] ), true )
		|| ! is_numeric( $allocation['invoice_total'] ?? null ) || ! is_finite( (float) $allocation['invoice_total'] ) || ! is_numeric( $allocation['paid_total'] ?? null ) || ! is_finite( (float) $allocation['paid_total'] )
		|| (float) $allocation['invoice_total'] < (float) $invoice_total || ( ! $payment_timing_allowed && round( (float) $allocation['paid_total'], 2 ) < round( (float) $allocation['invoice_total'], 2 ) ) ) {
		$f['blocker'] = 'Самовивіз потребує повної підтвердженої оплати замовлення та рахунків саме цього продавця. Перевірте журнал оплат.';
	}
	return $f;
}

