    private static function context_unscoped( $id ) {
		$order = absint( get_post_meta( $id, '_tkd_fo_delivery_order_id', true ) ); $invoice = absint( get_post_meta( $id, '_tkd_fo_delivery_invoice_id', true ) );
		if ( ! $order || ! $invoice || get_post_type( $order ) !== 'tkd_order' || get_post_type( $invoice ) !== 'tkd_invoice' || in_array( get_post_status( $invoice ), array( 'trash', 'auto-draft' ), true ) || in_array( get_post_status( $order ), array( 'trash', 'auto-draft' ), true )
			|| absint( get_post_meta( $invoice, '_tkd_fo_order_id', true ) ) !== $order ) { return self::error( 'Порушено зв’язок замовлення, рахунку й видаткової.' ); }
		$order_status = (string) get_post_meta( $order, '_tkd_status', true );
		if ( in_array( $order_status, array( 'cancelled', 'unavailable' ), true ) ) { return self::error( 'Замовлення скасоване або недоступне. Фізична видача заборонена.' ); }
		$items = get_post_meta( $id, '_tkd_fo_delivery_items', true ); $task = self::task( $id );
		if ( ! is_array( $items ) || ! $items || ! in_array( $task['state'] ?? '', array( 'collecting', 'ready' ), true ) ) { return self::error( 'Потрібне чинне завдання комплектації.' ); }
		$serials = array(); $nonserial = array(); $required = $task['required_source_indices'] ?? array();
		if ( ! is_array( $required ) ) { return self::error( 'Перелік товарів для сканування пошкоджено.' ); }
		foreach ( $items as $i => $line ) {
			$quantity = is_array( $line ) ? self::quantity( $line['quantity'] ?? null ) : null;
			if ( ! is_array( $line ) || empty( $line['sku'] ) || $quantity === null ) { return self::error( 'Некоректна кількість або товар видаткової.' ); }
			$list = preg_split( '/[\r\n,;]+/u', (string) ( $line['serial_numbers'] ?? '' ), -1, PREG_SPLIT_NO_EMPTY ); $list = array_map( 'trim', $list );
			$needs_serial = in_array( (int) ( $line['source_index'] ?? -1 ), array_map( 'intval', $required ), true );
			if ( ( $needs_serial || $list ) && ( !($serial_target=is_callable(array('TKD_Warehouse_Scanner','serial_target')) ? TKD_Warehouse_Scanner::serial_target($line) : (is_int($quantity)?$quantity:0)) || count($list)>$serial_target || ($task['state']==='ready'&&count($list)!==$serial_target) ) ) { return self::error( 'Серійні номери не покривають готову видаткову або кількість некоректна.' ); }
			if ( $list ) {
				foreach ( $list as $serial ) { $serial = strtoupper( preg_replace( '/\s+/', '', $serial ) ); if ( $serial === '' || isset( $serials[$serial] ) ) { return self::error( 'Порожній або повторний серійний номер.' ); } $serials[$serial] = (string) $line['sku']; }
			} else { $nonserial[(string) $i] = array( 'sku' => (string) $line['sku'], 'quantity' => $quantity ); }
		}
		ksort( $serials ); ksort( $nonserial );
		$context = array( 'delivery' => (int) $id, 'order' => $order, 'invoice' => $invoice, 'items' => $items, 'serials' => $serials, 'nonserial' => $nonserial, 'order_status' => $order_status, 'order_post_status' => get_post_status( $order ), 'invoice_post_status' => get_post_status( $invoice ),
			'mode' => self::mode( $order ), 'task_state' => $task['state'], 'assignee' => (int) ( $task['assignee_id'] ?? 0 ), 'required' => $required,
			'delivery_status' => get_post_meta( $id, '_tkd_fo_delivery_status', true ), 'stock_journal' => get_post_meta( $id, '_tkd_fo_delivery_stock_journal', true ),
			'seller' => get_post_meta( $id, '_tkd_fo_delivery_seller_key', true ), 'invoice_seller' => get_post_meta( $invoice, '_tkd_fo_seller_key', true ),
			'email' => (string) get_post_meta( $order, '_tkd_customer_email', true ), 'order_number' => (string) get_post_meta( $order, '_tkd_order_number', true ),
			'contact_channel' => (string) get_post_meta( $order, '_tkd_contact_channel', true ), 'phone' => (string) get_post_meta( $order, '_tkd_customer_phone', true ),
			'telegram' => (string) get_post_meta( $order, '_tkd_telegram_username', true ),
			'ttn' => (string) get_post_meta( $order, '_tkd_np_document_number', true ), 'profile' => (string) get_post_meta( $order, '_tkd_np_sender_profile_key', true ),
			'sender_tax' => (string) get_post_meta( $order, '_tkd_np_sender_tax_id', true ), 'sender_ref' => (string) get_post_meta( $order, '_tkd_np_sender_ref_snapshot', true ) );
		if ( ! $context['mode'] || $context['seller'] !== $context['invoice_seller'] ) { return self::error( 'Спосіб доставки або продавець потребує звірки.' ); }
		$context['financial'] = self::financial( $order, $invoice, $context['seller'] );
		return $context;
	}

private static function physical_fingerprint( $c ) {
	unset( $c['financial'], $c['order_status'] );
	return self::fingerprint( $c );
}

private static function completed_proof( $s, $c ) {
	unset( $s['completed_physical_v1'] );
	$p = array( 'version' => 1, 'delivery' => $c['delivery'], 'order' => $c['order'], 'physical' => self::physical_fingerprint( $c ), 'record' => self::fingerprint( $s ) );
	$p['signature'] = hash_hmac( 'sha256', wp_json_encode( $p ), wp_salt( 'auth' ) );
	return $p;
}

private static function fingerprint_matches( $s, $c ) {
	if ( is_string( $s['fingerprint'] ?? null ) && hash_equals( $s['fingerprint'], self::fingerprint( $c ) ) ) { return true; }
	if ( ( $s['state'] ?? '' ) !== 'handed_over' || ! in_array( $c['order_status'] ?? '', array( 'shipped', 'paid', 'deferred_payment' ), true ) || $c['delivery_status'] !== 'issued' || ! self::pickup_journal_matches( $c ) ) { return false; }
	$p = $s['completed_physical_v1'] ?? null;
	return is_array( $p ) && $p === self::completed_proof( $s, $c );
}

private static function contact_route( $c ) {
	$aliases = array( 'e-mail' => 'email', 'email' => 'email', 'sms' => 'sms', 'СМС' => 'sms', 'смс' => 'sms', 'viber' => 'viber', 'telegram' => 'telegram', 'whatsapp' => 'whatsapp', 'phone' => 'phone', 'Телефонний дзвінок' => 'phone', 'телефонний дзвінок' => 'phone' );
	$preferred = $aliases[ strtolower( trim( $c['contact_channel'] ) ) ] ?? 'unknown';
	$labels = array( 'email' => 'Email', 'sms' => 'SMS', 'viber' => 'Viber', 'telegram' => 'Telegram', 'whatsapp' => 'WhatsApp', 'phone' => 'Телефонний дзвінок', 'unknown' => 'Не визначено' );
	$route = array( 'preferred' => $preferred, 'label' => $labels[$preferred], 'channel' => '', 'notice' => '', 'recipient' => '' );
	if ( self::posting_completion_enabled() ) { $route['notice'] = 'Самовивіз завершується після проведення зібраної видаткової менеджером. Код клієнта не потрібний.'; return $route; }
	if ( ! self::pickup_enabled() ) { $route['notice'] = 'Надсилання нових кодів вимкнено. Уже надісланий чинний код можна підтвердити.'; return $route; }
	if ( $preferred === 'unknown' ) { $route['notice'] = 'Канал зв’язку в замовленні не визначено. Менеджер має уточнити його з клієнтом.'; return $route; }
	if ( $preferred !== 'email' && self::canonical_phone( $c['phone'] ) && is_callable( array( 'TKD_SMS_Service', 'pickup_ready' ) ) && TKD_SMS_Service::pickup_ready() === true ) {
		$route['channel'] = 'sms'; $route['recipient'] = '+380 ** *** ' . substr( self::canonical_phone( $c['phone'] ), -4 ); $route['notice'] = 'Код буде надіслано SMS на телефон клієнта з цього замовлення (не в месенджер).'; return $route;
