public static function enroll( $id ) {
	if ( ! self::manager() || ! self::can( $id ) ) { return self::error( 'Лише менеджер може почати контроль передачі.' ); }
	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
		self::fresh( $id ); $old = self::record( $id );
		if ( $old ) { return ( $old['version'] ?? 0 ) === 1 ? true : self::error( 'Невідома версія контролю передачі.' ); }
		if ( ! self::enrollment_available( $id ) ) { return self::error( 'Новий контроль доступний лише для чернетки самовивозу, коли цей процес увімкнено.' ); }
		$task = self::task( $id );
