			wp_cache_delete( $id, 'post_meta' ); if ( self::task( $id ) !== $marked ) { return self::error( 'Позначку контролю передачі не підтверджено.' ); }
		}
		$c = self::context( $id ); if ( is_wp_error( $c ) ) { return $c; }
		if ( $c['delivery_status'] !== 'draft' ) { return self::error( 'Історичні проведені видаткові автоматично не включаються в новий процес.' ); }
		$s = array( 'version' => 1, 'state' => 'preparing', 'mode' => $c['mode'], 'order' => $c['order'], 'created_at' => time(), 'scanned' => array(), 'counts' => array(), 'events' => array() );
		self::event( $s, 'enrolled' ); return self::save( $id, $old, $s );
