public static function status( $id ) {
	$s = self::record( $id ); $base = array( 'enabled' => ! empty( $s ) && ( $s['version'] ?? 0 ) === 1, 'mode' => $s['mode'] ?? '', 'state' => $s['state'] ?? 'disabled', 'blockers' => array() );
