	$base['scanned'] = $s['scanned'] ?? array(); $base['counts'] = $s['counts'] ?? array(); $base['manager'] = self::manager();
	$base['issued_ready'] = $c['delivery_status'] === 'issued' && $c['task_state'] === 'ready' && ! empty( $c['stock_journal'] );
