	if ( $c['financial']['blocker'] !== '' ) { $base['blockers'][] = $c['financial']['blocker']; }
	if ( ! self::posting_completion_enabled() && self::uncertain( $s ) ) { $base['blockers'][] = 'Результат попереднього надсилання невідомий. Повтор, резервний канал і скидання заблоковані; потрібна окрема звірка.'; }
	$base['contact_preferred'] = $route['preferred']; $base['contact_preferred_label'] = $route['label']; $base['code_channel'] = $route['channel']; $base['channel_notice'] = $route['notice']; $base['recipient_masked'] = $route['recipient'];
	if ( isset( $s['fingerprint'] ) && ! self::fingerprint_matches( $s, $c ) ) { $base['blockers'][] = 'Документи, серійні номери, контакт або ЕН змінилися після підготовки. Потрібна звірка менеджера.'; }
