private static function pickup_journal_matches( $c ) {
	if ( ! is_array( $c['stock_journal'] ) || ! $c['stock_journal'] ) { return false; }
	$expected = array(); $actual = array(); $ids = array();
	foreach ( $c['items'] as $line ) { $sku = strtoupper( trim( (string) $line['sku'] ) ); $expected[$sku] = round( ( $expected[$sku] ?? 0 ) + (float) $line['quantity'], 3 ); }
	foreach ( $c['stock_journal'] as $row ) {
		if ( ! is_array( $row ) || ! is_int( $row['item_id'] ?? null ) || $row['item_id'] <= 0 || isset( $ids[$row['item_id']] ) || ! is_string( $row['sku'] ?? null )
			|| self::quantity( $row['quantity'] ?? null ) === null || ! is_numeric( $row['reserved_released'] ?? null ) || ! is_finite( (float) $row['reserved_released'] )
			|| (float) $row['reserved_released'] < 0 || (float) $row['reserved_released'] > (float) $row['quantity'] ) { return false; }
		$sku = strtoupper( trim( $row['sku'] ) ); if ( $sku === '' || isset( $actual[$sku] ) ) { return false; }
		$ids[$row['item_id']] = true; $actual[$sku] = round( (float) $row['quantity'], 3 );
