	$expected = array_map( 'strval', array_keys( $c['serials'] ) ); $scanned = $s['scanned'] ?? array(); sort( $expected, SORT_STRING ); sort( $scanned, SORT_STRING ); return $expected === $scanned && ( $s['counts'] ?? array() ) === $c['nonserial'];
