			$fiscal = self::fiscal_guard( $id ); // Keep the known transport result even if receipt readiness changed in flight.
			$old = $s; $s['challenge']['state'] = $state; $s['challenge']['sent'] = $state === 'accepted'; $s['challenge']['message_id'] = $message_id;
			if ( $state === 'unknown' ) { $s['send_unknown'] = true; }
			self::event( $s, 'code_' . $state, array( 'channel' => $route['channel'] ) ); $saved = self::save( $id, $old, $s );
			if ( ! is_wp_error( $saved ) && is_wp_error( $fiscal ) ) { return $fiscal; }
			return is_wp_error( $saved ) ? $saved : ( $state === 'accepted' ? true : self::error( $state === 'unknown' ? 'Результат надсилання невідомий. Повтор, резервний канал і скидання заблоковані.' : 'Сервіс не прийняв код. Видачу не підтверджено; нова спроба можлива лише в межах ліміту.' ) );
