			if ( self::uncertain( $s ) || ! self::complete( $s, $c ) || empty( $ch['sent'] ) || ! in_array( $ch['channel'] ?? '', array( 'sms', 'email' ), true ) || ( $ch['expires'] ?? 0 ) <= time() || ( $ch['attempts'] ?? 5 ) >= 5 || $receiver === '' || strlen( $receiver ) > 600 || empty( $input['confirmed'] ) ) { return self::error( 'Потрібні всі перевірені товари, чинний код, одержувач і підтвердження фактичної видачі.' ); }
