}

private static function lock() {
	global $wpdb;
	$key = 'tkd_ws_' . substr( hash( 'sha256', ( defined( 'DB_NAME' ) ? DB_NAME : '' ) . '|' . $wpdb->prefix . '|' . ( function_exists( 'get_current_blog_id' ) ? get_current_blog_id() : 1 ) ), 0, 48 );
	return (string) $wpdb->get_var( $wpdb->prepare( 'SELECT GET_LOCK(%s,0)', $key ) ) === '1' ? $key : self::error( 'Інша складська дія виконується. Повторіть після її завершення.' );
