private static function fresh( $id ) {
	wp_cache_delete( $id, 'post_meta' ); wp_cache_delete( $id, 'posts' );
	foreach ( array( '_tkd_fo_delivery_order_id', '_tkd_fo_delivery_invoice_id' ) as $key ) { $other = self::id( get_post_meta( $id, $key, true ) ); if ( $other ) { wp_cache_delete( $other, 'post_meta' ); wp_cache_delete( $other, 'posts' ); } }
