private static function save( $id, $old, $new ) {
	$ok = $old ? update_post_meta( $id, self::META, wp_slash( $new ), $old ) : add_post_meta( $id, self::META, wp_slash( $new ), true );
	wp_cache_delete( $id, 'post_meta' ); return $ok && self::record( $id ) === $new ? true : self::error( 'Запис фізичного стану не підтверджено. Завдання залишається на звірці.' );
}

private static function contract() {
	if ( ! class_exists( 'TKD_FO_Deliveries' ) || ! defined( 'TKD_Warehouse_Scanner::VERSION' ) || version_compare( TKD_Warehouse_Scanner::VERSION, '0.1.6', '<' ) ) { return false; }
	if ( ! is_callable( array( 'TKD_Nova_Poshta_Bridge', 'dispatch_capabilities' ) ) || ! is_callable( array( 'TKD_Nova_Poshta_Bridge', 'dispatch_evidence' ) ) ) { return false; }
