private static function profile_enabled( $binding ) {
	$p = self::option( self::POLICY ); $v = $p['profiles'][$binding['profile']] ?? null;
	return self::enabled() && is_array( $v ) && ( $v['sender_ref'] ?? null ) === $binding['sender_ref'] && ( $v['sender_tax_id'] ?? null ) === $binding['sender_tax_id'];
