public static function enrollment_available( $id ) {
	if ( ! self::manager() || ! self::can( $id ) || ! self::enabled() || get_post_meta( $id, '_tkd_fo_delivery_status', true ) !== 'draft' ) { return false; }
	$order = self::id( get_post_meta( $id, '_tkd_fo_delivery_order_id', true ) ); $invoice = self::id( get_post_meta( $id, '_tkd_fo_delivery_invoice_id', true ) );
	$b = self::binding( $order, $id ); if ( is_wp_error( $b ) || ! self::profile_enabled( $b ) ) { return false; }
	if ( ( array( 'no_vat' => 'fop_iy', 'fop_pm' => 'fop_pm', 'fop_rv' => 'fop_rv', 'fop_tp' => 'fop_tp', 'fop_md' => 'fop_md' )[self::text( $invoice, '_tkd_fo_seller_key' )] ?? '' ) !== $b['profile'] ) { return false; }
	return self::active_post( $order, 'tkd_order' ) && self::active_post( $invoice, 'tkd_invoice' ) && self::id( get_post_meta( $invoice, '_tkd_fo_order_id', true ) ) === $order && self::mode( $order )
		&& ! in_array( get_post_meta( $order, '_tkd_status', true ), array( 'cancelled', 'unavailable' ), true ) && get_post_meta( $invoice, '_tkd_fo_invoice_status', true ) !== 'cancelled';
}

public static function assigned( $id, $task ) {
	if ( ! self::manager() || ! self::can( $id ) || ! is_array( $task ) || ( $task['dispatch_required'] ?? null ) !== 1 || ( $task['dispatch_mode'] ?? '' ) !== 'np' ) { return; }
	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
