		if ( ! self::enrollment_available( $id ) || self::task( $id ) !== $task || ! in_array( $task['state'] ?? '', array( 'collecting', 'ready' ), true ) ) { return self::error( 'Потрібна нова чернетка й чинне завдання Нової пошти.' ); }
		return self::save( $id, array(), array( 'version' => 1, 'mode' => 'np', 'state' => 'preparing', 'order' => self::id( get_post_meta( $id, '_tkd_fo_delivery_order_id', true ) ), 'created_at' => time(), 'enrolled_by' => get_current_user_id() ) );
	} finally { self::unlock( $lock ); }
