	if ( ! self::active_post( $id, 'tkd_delivery' ) || ! self::active_post( $order, 'tkd_order' ) || ! self::active_post( $invoice, 'tkd_invoice' ) || self::id( get_post_meta( $invoice, '_tkd_fo_order_id', true ) ) !== $order || ! self::mode( $order )
		|| in_array( get_post_meta( $order, '_tkd_status', true ), array( 'cancelled', 'unavailable' ), true ) || get_post_meta( $invoice, '_tkd_fo_invoice_status', true ) === 'cancelled' ) { return self::error( 'Замовлення/рахунок/видаткова скасовані або їх зв’язок чи доставка змінилися.' ); }
