		$source_rows[$index] = array( $row['sku'], $row['name'], $row['unit'], (float) $row['quantity'] );
	}
	if ( ! is_string( $task['source_guard'] ?? null ) || ! hash_equals( hash( 'sha256', serialize( array( $invoice, $source_rows ) ) ), $task['source_guard'] ) ) { return self::error( 'Рахунок змінився після призначення комплектації.' ); }
