		$quantities[$line['sku']] = round( ( $quantities[$line['sku']] ?? 0 ) + (float) $line['quantity'], 3 );
		$list = array_values( array_filter( array_map( 'trim', preg_split( '/[\r\n,;]+/u', $line['serial_numbers'] ?? '' ) ), 'strlen' ) );
		$required = in_array( $index, $task['required_source_indices'], true );
		if ( ( $required || $list ) && ( !($serial_target=is_callable(array('TKD_Warehouse_Scanner','serial_target')) ? TKD_Warehouse_Scanner::serial_target($line) : (floor((float)$line['quantity'])===(float)$line['quantity']?(int)$line['quantity']:0)) || count($list)>$serial_target || (($ready||$late_candidate)&&count($list)!==$serial_target) ) ) { return self::error( 'Не всі серійні номери відповідають готовій видатковій.' ); }
