	foreach ( array( '_tkd_np_delivery_method', '_tkd_np_last_name', '_tkd_np_first_name', '_tkd_np_middle_name', '_tkd_np_phone', '_tkd_np_city_ref', '_tkd_np_settlement_ref', '_tkd_np_street_ref', '_tkd_np_building', '_tkd_np_flat', '_tkd_np_warehouse_ref', '_tkd_np_address' ) as $key ) { $c['shipping'][$key] = get_post_meta( $order, $key, true ); }
	return $c;
}

private static function prepost_claim_guard( $c, $draft = false ) {
	$key = self::prepost_claim_key( $c['binding']['ttn'] ); self::option_fresh( $key ); $claim = get_option( $key, null );
	if ( $claim === null ) { return true; }
	return is_array( $claim ) && ( $claim['version'] ?? null ) === 1 && ( $claim['delivery'] ?? null ) === $c['delivery'] && ( $claim['binding'] ?? null ) === $c['binding']
		&& ( ! $draft || ( $claim['draft_fingerprint'] ?? '' ) === self::fingerprint( $c ) ) ? true : self::error( 'ЕН уже закріплена перед списанням за іншою видатковою або її склад змінився. Потрібна звірка.' );
}

private static function claim_before_post( $c ) {
	$guard = self::prepost_claim_guard( $c, true ); if ( is_wp_error( $guard ) ) { return $guard; }
	$key = self::prepost_claim_key( $c['binding']['ttn'] ); self::option_fresh( $key );
	$expected = array( 'version' => 1, 'delivery' => $c['delivery'], 'binding' => $c['binding'], 'draft_fingerprint' => self::fingerprint( $c ) );
	if ( get_option( $key, null ) === $expected ) { return true; }
	if ( ! add_option( $key, $expected, '', false ) ) { return self::error( 'Не вдалося закріпити ЕН до списання. Склад не змінено.' ); }
	self::option_fresh( $key ); return get_option( $key, null ) === $expected ? true : self::error( 'Закріплення ЕН до списання не підтверджено. Повторне списання заборонено до звірки.' );
}

private static function unique_order( $c ) {
	global $wpdb;
	$ids = $wpdb->get_col( $wpdb->prepare( "SELECT DISTINCT p.ID FROM {$wpdb->posts} p INNER JOIN {$wpdb->postmeta} m ON m.post_id=p.ID WHERE p.post_type='tkd_order' AND m.meta_key='_tkd_np_document_number' AND m.meta_value=%s LIMIT 2", $c['binding']['ttn'] ) );
	return is_array( $ids ) && count( $ids ) === 1 && (int) $ids[0] === $c['order'];
}

private static function claim( $c ) {
	if ( ! self::unique_order( $c ) ) { return self::error( 'Ця ЕН не має унікального зв’язку із замовленням. Потрібна звірка.' ); }
	$key = self::claim_key( $c['binding']['ttn'] ); self::option_fresh( $key ); $old = get_option( $key, null );
	if ( $old !== null ) { return $old === self::claim_value( $c ) ? true : self::error( 'ЕН уже закріплена за іншою видатковою або незмінним складом товарів.' ); }
	return add_option( $key, self::claim_value( $c ), '', false ) && self::owns_claim( $c ) ? true : self::error( 'Не вдалося надійно закріпити ЕН. Повторна передача не підтверджена.' );
}

private static function utc( $v ) {
	if ( ! is_string( $v ) || ! preg_match( '/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/D', $v ) ) { return false; }
	$d = DateTimeImmutable::createFromFormat( '!Y-m-d H:i:s', $v, new DateTimeZone( 'UTC' ) ); return $d && $d->format( 'Y-m-d H:i:s' ) === $v ? $d->getTimestamp() : false;
}

private static function evidence( $raw, $binding, $fresh = true ) {
	if ( ! is_array( $raw ) || ( $raw['source'] ?? '' ) !== 'np_tracking_document' || ! is_bool( $raw['accepted'] ?? null ) || ! is_string( $raw['state_code'] ?? null ) || ! preg_match( '/^[0-9]{1,3}$/D', $raw['state_code'] ) || ! is_string( $raw['state_label'] ?? null ) || $raw['state_label'] === '' || strlen( $raw['state_label'] ) > 600 ) { return self::error( 'Нова пошта не надала перевіреного нормалізованого стану. Завдання залишається відкритим.' ); }
	foreach ( $binding as $k => $v ) { if ( ( $raw[$k] ?? null ) !== $v ) { return self::error( 'Доказ Нової пошти не збігається з точною ЕН або її відправником.' ); } }
	$t = self::utc( $raw['checked_at'] ?? null ); if ( $t === false || $t > time() + 30 || ( $fresh && $t < time() - 300 ) ) { return self::error( 'Стан Нової пошти застарілий або має некоректний час перевірки.' ); }
	if ( ( ! $raw['accepted'] && $raw['state_code'] !== '1' ) || $raw['accepted'] !== in_array( $raw['state_code'], self::$accepted_codes, true ) ) { return self::error( 'Суперечливий або невідомий статус фізичного приймання Новою поштою.' ); }
	$out = array_merge( array( 'source' => 'np_tracking_document' ), $binding, array( 'accepted' => $raw['accepted'], 'state_code' => $raw['state_code'], 'state_label' => sanitize_text_field( $raw['state_label'] ), 'checked_at' => $raw['checked_at'] ) );
	return $out;
}

private static function fetch( $b ) {
	try { $raw = TKD_Nova_Poshta_Bridge::dispatch_evidence( $b['order'], $b['ttn'], $b['profile'] ); }
	catch ( Throwable $e ) { return self::error( 'Зв’язок із Новою поштою недоступний. Передачу не підтверджено.' ); }
	if ( is_wp_error( $raw ) ) {
		$code = $raw->get_error_code();
		$known = array( 'np_dispatch_order_invalid', 'np_dispatch_ttn_invalid', 'np_dispatch_ttn_changed', 'np_dispatch_profile_invalid', 'np_dispatch_sender_unverified', 'np_dispatch_sender_changed', 'np_dispatch_ref_unverified', 'np_dispatch_key_missing', 'np_dispatch_document_match', 'np_dispatch_document_owner', 'np_dispatch_document_deleted', 'np_dispatch_tracking_match', 'np_dispatch_tracking_state', 'np_dispatch_tracking_exception', 'np_dispatch_tracking_label', 'np_dispatch_identity_changed', 'np_dispatch_method', 'np_dispatch_transport', 'np_dispatch_response' );
		$diagnostic = is_string( $code ) && in_array( $code, $known, true ) ? $code : '';
		if ( $code === 'np_dispatch_response' ) {
			$data = $raw->get_error_data();
			// Only these literals generated by our bridge are public. Never forward provider text/data.
			if ( is_array( $data ) && in_array( $data['stage'] ?? null, array( 'document', 'tracking' ), true )
				&& in_array( $data['category'] ?? null, array( 'json', 'success', 'shape', 'errors', 'warnings' ), true ) ) {
				$diagnostic .= '; stage=' . $data['stage'] . '; category=' . $data['category'];
			}
		}
		return self::error( 'Перевірку НП не підтверджено' . ( $diagnostic !== '' ? ' [' . $diagnostic . ']' : '' ) . '. Відправлення залишається на звірці.' );
	}
	return self::evidence( $raw, $b );
}

public static function manager_release_plan( $id, $task ) {
	self::fresh( $id );
	if ( ! self::manager() || ! self::can( $id ) || ! current_user_can( 'edit_post', $id ) || ! self::enrollment_available( $id ) || ! is_array( $task ) || ( $task['state'] ?? '' ) !== 'ready' || ( $task['dispatch_required'] ?? null ) !== 1 || ( $task['dispatch_mode'] ?? '' ) !== 'np' ) { return self::error( 'Потрібні збережена ЕН, увімкнений профіль її відправника та чинна чернетка видаткової.' ); }
	$raw = get_post_meta( $id, self::META, true ); $s = self::record( $id );
	if ( $raw !== '' && ( ! is_array( $raw ) || ( $s['version'] ?? null ) !== 1 || ( $s['mode'] ?? '' ) !== 'np' || ( $s['state'] ?? '' ) !== 'preparing' || ( $s['order'] ?? null ) !== self::id( get_post_meta( $id, '_tkd_fo_delivery_order_id', true ) ) ) ) { return self::error( 'Контроль НП уже змінений або має невідомий стан. Повторна підготовка заборонена.' ); }
	foreach ( array( 'reconciliation', 'fingerprint', 'baseline', 'carrier', 'probe_pending', 'initial_rejected', 'late_enrollment' ) as $key ) {
		if ( isset( $s[$key] ) ) { return self::error( 'Є попередня перевірка або незавершена передача НП. Потрібна звірка чинного завдання.' ); }
	}
	$c = self::context( $id, false, true, $task ); if ( is_wp_error( $c ) ) { return $c; }
	if ( ! current_user_can( 'edit_post', $c['order'] ) || ! current_user_can( 'edit_post', $c['invoice'] ) || ! self::unique_order( $c ) ) { return self::error( 'ЕН має неоднозначний зв’язок або документи недоступні.' ); }
	foreach ( array( self::claim_key( $c['binding']['ttn'] ), self::prepost_claim_key( $c['binding']['ttn'] ) ) as $key ) {
		self::option_fresh( $key ); if ( get_option( $key, null ) !== null ) { return self::error( 'ЕН уже закріплена попередньою операцією. Потрібна звірка без повторного списання.' ); }
	}
	return array( 'record' => $s ?: array( 'version' => 1, 'mode' => 'np', 'state' => 'preparing', 'order' => $c['order'] ), 'revision' => self::revision( $id, $s, $c ) );
}

public static function preflight_before_post( $id, $revision ) {
	if ( ( $_SERVER['REQUEST_METHOD'] ?? '' ) !== 'POST' || ! self::manager() || ! self::can( $id ) || ! current_user_can( 'edit_post', $id ) || ! is_string( $revision ) || ! is_callable( array( 'TKD_Warehouse_Scanner', 'office_revision' ) ) ) { return self::error( 'Перевірку нової ЕН підтверджує менеджер.' ); }
	check_admin_referer( 'tkd_np_dispatch_' . $id );
	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
		self::fresh( $id ); $s = self::record( $id ); $c = self::context( $id, false ); $task = self::task( $id );
		$status = self::status( $id, true );
		if ( is_wp_error( $c ) || get_post_meta( $id, '_tkd_fo_delivery_status', true ) !== 'draft' || ( $task['state'] ?? '' ) !== 'ready'
			|| ! empty( $status['blockers'] ) || ( $status['enabled'] ?? false ) !== true || ( $s['state'] ?? '' ) !== 'preparing'
			|| ! hash_equals( self::revision( $id, $s, $c ), $revision ) || ! self::unique_order( $c ) ) { return self::error( 'Нова ЕН або готовність видаткової потребує звірки до списання.' ); }
		$before = array( $c, $s, $task, get_post_meta( $id, '_tkd_fo_delivery_handover_post_v1', true ), TKD_Warehouse_Scanner::office_revision( $id ) );
		if ( $before[3] !== '' || ! in_array( $c['journal'], array( '', array() ), true ) || get_post_meta( $id, '_tkd_fo_delivery_stock_processed_at', true ) !== '' ) { return self::error( 'Є сліди попереднього проведення. Нове списання заблоковано.' ); }
	} finally { self::unlock( $lock ); }
	$proof = self::fetch( $c['binding'] );
	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
		self::fresh( $id ); $now = self::context( $id, false );
		if ( is_wp_error( $now ) || array( $now, self::record( $id ), self::task( $id ), get_post_meta( $id, '_tkd_fo_delivery_handover_post_v1', true ), TKD_Warehouse_Scanner::office_revision( $id ) ) !== $before
			|| get_post_meta( $id, '_tkd_fo_delivery_status', true ) !== 'draft' || ! self::profile_enabled( $now['binding'] ) || ! self::unique_order( $now ) ) { return self::error( 'Документи або контроль НП змінилися під час перевірки. Списання не починали.' ); }
		if ( is_wp_error( $proof ) ) { return $proof; }
		$proof = self::evidence( $proof, $now['binding'] );
		if ( is_wp_error( $proof ) ) { return $proof; }
		if ( $proof['accepted'] !== false || $proof['state_code'] !== '1' ) { return self::error( 'НП підтвердила стан ' . $proof['state_code'] . ': ' . $proof['state_label'] . ' Якщо чек уже є — відкрийте «Посилка вже в дорозі — провести видаткову». Якщо чека немає — потрібне окреме підтвердження пропущеного чека поточним часом. Повторне списання не виконується.' ); }
		$key = self::claim_key( $now['binding']['ttn'] ); self::option_fresh( $key );
		if ( get_option( $key, null ) !== null ) { return self::error( 'ЕН уже закріплена проведеною видатковою. Нове списання не починали.' ); }
		// One EN may have several draft notes. Claim its owner before any of them can debit stock.
		return self::claim_before_post( $now );
	} finally { self::unlock( $lock ); }
}

public static function status( $id, $for_release_prepare = false ) {
	$out = array( 'enabled' => false, 'mode' => 'np', 'state' => 'preparing', 'blockers' => array(), 'url' => '', 'preparation_valid' => false, 'warning' => '' );
	if ( self::id( $id ) ) { self::fresh( $id ); }
	if ( ! self::can( $id ) ) { $out['blockers'][] = 'Немає доступу до цієї видаткової.'; return $out; }
	$out['url'] = self::url( $id ); $s = self::record( $id );
	if ( ! $s ) { $out['blockers'][] = 'Ця видаткова не включена в новий контроль НП. Історичні документи автоматично не додаються.'; return $out; }
	$c = self::context( $id, false );
	if ( ( $s['version'] ?? null ) !== 1 || ( $s['mode'] ?? '' ) !== 'np' || ! in_array( $s['state'] ?? '', array( 'preparing', 'awaiting_handover', 'handed_over' ), true ) || is_wp_error( $c ) || ( $s['order'] ?? null ) !== ( $c['order'] ?? null ) ) { $out['blockers'][] = is_wp_error( $c ) ? $c->get_error_message() : 'Запис контролю НП пошкоджений.'; return $out; }
	$out['enabled'] = true; $out['state'] = $s['state']; $out['revision'] = self::revision( $id, $s, $c );
	if ( isset( $s['reconciliation'] ) ) {
		$valid = self::reconciliation_record_valid( $s, $c, self::task( $id ) ) && self::unique_order( $c ) && ! is_wp_error( self::prepost_claim_guard( $c, get_post_meta( $id, '_tkd_fo_delivery_status', true ) === 'draft' ) );
		if ( $s['state'] === 'handed_over' ) {
			$ready = self::context( $id, true ); $intent = get_post_meta( $id, '_tkd_fo_delivery_handover_post_v1', true );
			$proof = self::evidence( $s['carrier'] ?? null, $c['binding'], false );
			$valid = $valid && ! is_wp_error( $ready ) && ( $s['reconciliation']['phase'] ?? '' ) === 'completed' && ( $s['fingerprint'] ?? '' ) === self::fingerprint( $c ) && self::owns_claim( $c )
				&& is_array( $intent ) && ( $intent['state'] ?? '' ) === 'committed' && ( $intent['notification'] ?? '' ) === 'completed'
				&& ! is_wp_error( $proof ) && $proof['accepted'] === true && self::utc( $proof['checked_at'] ) >= self::utc( $s['reconciliation']['proof']['checked_at'] ?? '' );
			if ( $valid ) { $out['evidence'] = $proof; $out['reconciled'] = true; }
		} else { $valid = $valid && $s['state'] === 'preparing' && ( $s['reconciliation']['phase'] ?? '' ) === 'admitted' && self::profile_enabled( $c['binding'] ); }
		if ( ! $valid ) { $out['enabled'] = false; $out['state'] = 'preparing'; $out['blockers'][] = 'Незмінний запис звірки вже відправленої ЕН потребує перевірки. Повторне списання заборонене.'; }
		elseif ( $s['state'] !== 'handed_over' && $for_release_prepare ) { $out['blockers'][] = 'Завершіть окрему дію «Вже передано НП»; звичайна підготовка не застосовується.'; }
		return $out;
	}
	$retry = $for_release_prepare === true && $s['state'] === 'preparing' && empty( $s['initial_rejected'] );
	if ( $for_release_prepare === true && ! self::profile_enabled( $c['binding'] ) ) { $out['blockers'][] = 'Профіль відправника не ввімкнено для контролю передачі.'; }
	if ( $for_release_prepare === true ) {
		$draft = get_post_meta( $id, '_tkd_fo_delivery_status', true ) === 'draft';
		$admission = self::prepost_claim_guard( $c, $draft ); if ( is_wp_error( $admission ) ) { $out['blockers'][] = $admission->get_error_message(); }
		if ( $draft ) { $key = self::claim_key( $c['binding']['ttn'] ); self::option_fresh( $key ); if ( get_option( $key, null ) !== null ) { $out['blockers'][] = 'ЕН уже закріплена проведеною видатковою. Нове списання заблоковане.'; } }
	}
	if ( ! empty( $s['probe_pending'] ) && ( ! $retry || ( $s['probe_until'] ?? 0 ) > time() ) ) { $out['blockers'][] = ( $s['probe_until'] ?? 0 ) > time() ? 'Перша перевірка ЕН виконується; зачекайте до хвилини.' : 'Перша перевірка перервана. Менеджер може безпечно повторити читання стану тієї самої ЕН.'; }
	if ( ! empty( $s['initial_rejected'] ) ) { $out['blockers'][] = 'Перша перевірка виявила вже прийняту ЕН. Історичне відправлення не можна включити повторно.'; }
	if ( isset( $s['fingerprint'] ) && ( ! is_string( $s['fingerprint'] ) || ! hash_equals( $s['fingerprint'], self::fingerprint( $c ) ) || ! self::owns_claim( $c ) || ! self::unique_order( $c ) ) ) { $out['blockers'][] = 'Склад документів або незмінний зв’язок ЕН змінився. Потрібна звірка менеджера.'; }
	if ( $s['state'] !== 'preparing' ) {
		$ready = self::context( $id, true ); if ( is_wp_error( $ready ) ) { $out['blockers'][] = $ready->get_error_message(); }
		if ( empty( $s['fingerprint'] ) || ! isset( $s['baseline'] ) || is_wp_error( self::evidence( $s['baseline'], $c['binding'], false ) ) || ( $s['baseline']['state_code'] ?? '' ) !== '1' || ( $s['baseline']['accepted'] ?? null ) !== false ) { $out['blockers'][] = 'Немає первинного підтвердження нової ЕН (стан 1).' ; }
	}
	if ( $s['state'] === 'handed_over' ) {
		$proof = self::evidence( $s['carrier'] ?? null, $c['binding'], false );
		if ( is_wp_error( $proof ) || ( $proof['accepted'] ?? null ) !== true || self::utc( $proof['checked_at'] ?? null ) < self::utc( $s['baseline']['checked_at'] ?? null ) ) { $out['blockers'][] = 'Немає незмінного підтвердження фактичного приймання НП.'; }
		elseif ( ! $out['blockers'] ) { $out['evidence'] = $proof; }
	}
	if ( $s['state'] === 'awaiting_handover' && ! $out['blockers'] ) {
		$admission = self::prepost_claim_guard( $c );
		if ( is_wp_error( $admission ) ) { $out['blockers'][] = $admission->get_error_message(); }
		if ( ! self::profile_enabled( $c['binding'] ) ) { $out['blockers'][] = 'Профіль контролю НП вимкнено або його реквізити змінилися. Потрібна звірка.'; }
		// A transient polling failure is not evidence that a prepared parcel left the warehouse.
		if ( ! $out['blockers'] && ( empty( $s['last_error'] ) || $s['last_error'] === 'carrier_unverified' ) ) {
			$out['preparation_valid'] = true;
			if ( ( $s['last_error'] ?? '' ) === 'carrier_unverified' ) { $out['warning'] = 'carrier_unverified'; }
		}
	}
	if ( ! empty( $s['last_error'] ) && ! ( $retry && in_array( $s['last_error'], array( 'baseline_not_new', 'release_changed' ), true ) ) ) { $out['blockers'][] = 'Останню перевірку НП не підтверджено. Очікується наступна перевірка або звірка менеджера.'; }
	if ( $out['blockers'] && $out['state'] === 'handed_over' ) { $out['state'] = 'awaiting_handover'; }
	return $out;
}

private static function reconciliation_identity( $c ) {
	unset( $c['journal'], $c['documents']['_tkd_fo_delivery_stock_processed_at'] );
	return self::fingerprint( $c );
}

private static function reconciliation_record_valid( $s, $c, $task ) {
	$r = $s['reconciliation'] ?? null;
	if ( ! is_array( $r ) || ( $r['version'] ?? null ) !== 1 || ( $r['kind'] ?? '' ) !== 'already_accepted_np' || ! in_array( $r['phase'] ?? '', array( 'admitted', 'completed' ), true )
		|| ( $s['version'] ?? null ) !== 1 || ( $s['mode'] ?? '' ) !== 'np' || ( $s['order'] ?? null ) !== $c['order'] || ! self::id( $s['prepared_by'] ?? 0 )
		|| ( $r['context_hash'] ?? '' ) !== self::reconciliation_identity( $c ) || ( $r['task_hash'] ?? '' ) !== hash( 'sha256', serialize( $task ) )
		|| ! is_array( $r['original_task'] ?? null ) || ! is_string( $r['business_basis'] ?? null ) || ! preg_match( '/^[a-f0-9]{64}$/D', $r['business_basis'] ) ) { return false; }
	$proof = self::evidence( $r['proof'] ?? null, $c['binding'], false );
	return ! is_wp_error( $proof ) && $proof['accepted'] === true;
}

private static function fiscal_guard( $id ) {
	if ( ! is_callable( array( 'TKD_Sales_Fiscal_Gate', 'check_delivery' ) ) ) { return self::error( 'Фіскальна перевірка недоступна. Нову підготовку передачі НП заблоковано.' ); }
	try { $result = TKD_Sales_Fiscal_Gate::check_delivery( (int) $id ); }
	catch ( Throwable $error ) { return self::error( 'Фіскальну перевірку не завершено. Передачу НП не підготовлено.' ); }
	return $result === true ? true : ( is_wp_error( $result ) ? $result : self::error( 'Немає однозначного підтвердження фіскальної готовності.' ) );
}

public static function prepare( $id, $revision, $confirmed, $preflight = null ) {
	if ( ( $_SERVER['REQUEST_METHOD'] ?? '' ) !== 'POST' || ! self::manager() || ! self::can( $id ) ) { return self::error( 'Підготовку підтверджує лише менеджер.' ); }
