	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
		self::fresh( $id ); $s = self::record( $id ); $c = self::context( $id );
		if ( is_wp_error( $c ) ) { return $c; }
		if ( isset( $s['reconciliation'] ) ) { return self::error( 'Використайте окрему дію звірки вже переданої ЕН.' ); }
		$fiscal = self::fiscal_guard( $id ); if ( is_wp_error( $fiscal ) ) { return $fiscal; }
		if ( $preflight !== null ) {
