		}
		if ( ! self::profile_enabled( $c['binding'] ) || ! $confirmed || ( $s['version'] ?? null ) !== 1 || ( $s['mode'] ?? '' ) !== 'np' || ( $s['order'] ?? null ) !== $c['order'] || ( $s['state'] ?? '' ) !== 'preparing' || ( ! empty( $s['probe_pending'] ) && ( $s['probe_until'] ?? 0 ) > time() ) || ! empty( $s['initial_rejected'] )
			|| ! is_string( $revision ) || ! hash_equals( self::revision( $id, $s, $c ), $revision ) || ( isset( $s['fingerprint'] ) && $s['fingerprint'] !== self::fingerprint( $c ) ) ) { return self::error( 'Дані підготовки змінилися, профіль вимкнено або перевірка вже виконується.' ); }
		$admission = self::prepost_claim_guard( $c ); if ( is_wp_error( $admission ) ) { return $admission; }
		$claim = self::claim( $c ); if ( is_wp_error( $claim ) ) { return $claim; }
		$old = $s; $s['fingerprint'] = self::fingerprint( $c ); $s['binding'] = $c['binding']; $s['probe_pending'] = bin2hex( random_bytes( 16 ) ); $s['probe_until'] = time() + 60; $s['prepared_by'] = get_current_user_id();
