	$lock = self::lock(); if ( is_wp_error( $lock ) ) { return $lock; }
	try {
		self::fresh( $id ); $now = self::context( $id );
		if ( is_wp_error( $now ) || self::record( $id ) !== $s || self::fingerprint( $now ) !== self::fingerprint( $c ) || ! self::owns_claim( $now ) || ! self::unique_order( $now ) || ! self::profile_enabled( $now['binding'] ) ) { return self::error( 'Дані змінилися під час першої перевірки. Автоматичне підтвердження заблоковано.' ); }
		$new = $s; unset( $new['probe_pending'], $new['probe_until'] );
		$fiscal = self::fiscal_guard( $id );
		if ( is_wp_error( $fiscal ) ) { $new['last_error'] = 'release_changed'; self::save( $id, $s, $new ); return $fiscal; }
		if ( $preflight !== null ) {
			$check = call_user_func( $preflight );
			if ( $check !== true ) { $new['last_error'] = 'release_changed'; self::save( $id, $s, $new ); return is_wp_error( $check ) ? $check : self::error( 'Дані підготовки змінилися під час перевірки НП.' ); }
		}
		if ( is_wp_error( $proof ) || $proof['accepted'] !== false || $proof['state_code'] !== '1' ) { $new['last_error'] = 'baseline_not_new'; if ( ! is_wp_error( $proof ) ) { $new['initial_rejected'] = $proof; } self::save( $id, $s, $new ); return self::error( 'Початкова перевірка має підтвердити нову ЕН у стані 1. Історичну або вже прийняту посилку не включено.' ); }
		$new['baseline'] = $proof; $new['state'] = 'awaiting_handover'; $new['armed_at'] = gmdate( 'Y-m-d H:i:s' ); unset( $new['last_error'] );
		return self::save( $id, $s, $new );
	} finally { self::unlock( $lock ); }
}
